quests[26597] = { id = 26597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick... have contracted Stranglethorn Fever....\n\n...technically... CAPE of Stranglethorn Fever....\n\n...deadly v-v-virus....\n\n...only cure... is... is... to eat the heart of M-m-m-m-mokk the Savage... elusive white beast....\n\n...Witch Doctor Unbagwa... only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape....\n\n...hurry... dying... dying....", sourceObjective = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might I be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me....", sourceObjectiveStatus = "unverified-source-field" }
quests[26598] = { id = 26598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Mokk", progress = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!", completion = "Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.\n\nYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!" }
quests[26599] = { id = 26599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  I will not rest until their corpses pepper the ocean floor!\n\nOne of the giants, Gorlash, stole my captain's chest.  I hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", sourceObjective = "Obtain Smotts' Chest from Gorlash in the Cape of Stranglethorn.", progress = "Ahoy, {name}!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it!  What a glorious day for ol' Hecklebury, this is.  Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete...", sourceObjectiveStatus = "unverified-source-field" }
quests[26600] = { id = 26600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Giant's Feast", description = "The next giant on my list is called Negolash.  I remember vividly how he leapt from the seafoam and plucked poor Poop-Deck Paul from the crow's nest.\n\nSwallowed him in one gulp, he did.  And snapped my mizzenmast in two on the way down.\n\nNo man on my crew deserves such a heinous death.  So we're going to use Negolash's appetite against him.  Kelsey Yance should be able to sell you some meat, and Whiskey Slim has enough booze to knock out... well, a sea giant.  You'll find both of them in town.", sourceObjective = "Purchase a Crate of Grade-E Meat from Kelsey Yance and a Crate of Pupellyverbos Port from Whiskey Slim.", progress = "We're going to need a lot of food, {name}.  Quantity over quality is the goal here.", completion = "This wasn't expensive, was it?  Well, here's some pieces of eight to reimburse you.\n\nNow let's get onto this revenge, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[26601] = { id = 26601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'rash the Cleaver", description = "Mok'rash the Cleaver is the last of the lot.  And the largest, by my memory.  Taller than a wave in a windstorm, with a beard like a kelp forest and a hammer like an oak tree.\n\nHe taunts me from Janeiro's Point, the island right off the end of this very pier.  It's because of him that I'm still trapped here, living this lamentable landlubber's life.\n\nIf you can swim, then head out to Janeiro's Point and slay Mok'rash.\n\nTake care, {name}.  Mok'rash will not lay down as easily as his brothers.", sourceObjective = "Kill Mok'rash the Cleaver at Janeiro's Point.", completion = "Mok'rash... Negolash... Gorlash... they're all gone.\n\nI suppose I have no excuses now.  I can return to the high seas and a life of pillage and booty!  And it's all thanks to you.\n\nNow I just need to get myself a ship...", sourceObjectiveStatus = "unverified-source-field" }
quests[26602] = { id = 26602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish Best Served Huge", description = "Take this food, and put it in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come running!\n\nAnd when he does, there will be a stouthearted {class} ready to knock his corpse back into the briny deep.", sourceObjective = "Bring the Giant Crate of Giant Food to Captain Smotts' lifeboat, then use it to summon and kill Negolash.", completion = "I can't believe my fortune, {name}!  Meeting you has turned my luck to the better, make no mistake there!\n\nIf I ever get a new ship and you're looking to sail the seas, you would be my honored guest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26603] = { id = 26603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message in a Bottle", description = "Inside the bottle you find a note which reads, in fairly good handwriting:\n\n<To any that can aid me->\n\n<Please, my need for help is dire. A great beast holds me captive on an island in the South Seas.>\n\n<The stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see shoreline to the northwest, and what seem to be large sailing ships to the southwest.>\n\n<I beg of you, my would-be savior, please help me.>", sourceObjective = "Find the author of the message at Jaguero Isle in the Cape of Stranglethorn.", completion = "Have you come to free me?", sourceObjectiveStatus = "unverified-source-field" }
quests[26604] = { id = 26604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Her Royal Highness Poobah", description = "These vicious jungle cats have been circling me for some time now.  I watch them as closely as I can, but they seem to just... disappear into the grass.\n\nHow they snarl and hiss!\n\nDon't get me wrong... I still want you to rescue me, but first, clear out some of these cats.  I won't need to be rescued if I end up someone's dinner.", sourceObjective = "Slay 5 Jaguero Stalkers.", progress = "Please, my hero, dispose of the stalking panthers!", completion = "It's about time you returned.  I was beginning to worry that I was going to be eaten while you hunted.\n\nA cat eating a princess... wouldn't that be a fancy feast?", sourceObjectiveStatus = "unverified-source-field" }
quests[26605] = { id = 26605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubby Little Paws", description = "I understand that you're anxious to rescue me, but the time is not yet right.  First I'm going to need some of my things.\n\nThe gorillas and the monkeys on the other side of the island have taken most of my possessions.  I'll need my tiara, my scepter, my slippers, and my diary before I'm ready to leave.\n\nWhat?  Stop looking at me like I'm some sort of insane person.  You don't know what it's like being a princess.", sourceObjective = "Obtain Poobah's Tiara, Poobah's Scepter, Poobah's Slippers, and Poobah's Diary from the apes on Jaguero Isle.", progress = "I shudder to think what Mukla plans to do with me.", completion = "<Poobah surveys her belongings.>\n\nLooks like it's all here.  Alright, I think I'm ready to be rescued now.", sourceObjectiveStatus = "unverified-source-field" }
quests[26606] = { id = 26606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mukla's Demise", description = "{name}, I now put my faith in you to help free me.  The great Skymane King Mukla is my captor.  He commands the beasts of this island, and they keep me here against my will with the aid of this chain.  If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", sourceObjective = "Slay King Mukla obtain the Shackle Key.", progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "{name}, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.", sourceObjectiveStatus = "unverified-source-field" }
quests[26607] = { id = 26607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Drew First Blood", description = "Take this bundle of Keeshan's possessions and head back to the Lakeshire inn basement. Bravo Company is already there, talking to Keeshan. Remind him of who drew first blood, {name}. Lakeshire needs Keeshan. The Alliance needs Keeshan.\n\nDismissed, soldier!", sourceObjective = "Deliver Keeshan's Possessions to John J. Keeshan at the Lakeshire Inn in Redridge.", progress = "You again?", completion = "<Keeshan takes the bundle from you and opens it.>\n\nMy bow... and knife! Where did you...\n\nJade's amulet... My darling Jade.\n\n<Keeshan picks up his red headband.>\n\nWe got orcs to kill.", sourceObjectiveStatus = "unverified-source-field" }
quests[26608] = { id = 26608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations Terminated", description = "Go now, go back to your fleet. Tell them what kind of a monster claims authority over the Dragonmaw.\n\nOur \"Warchief\" is a traitor to his blood. Since his return from Outland he reeks of demon and leads what remains of our clan to ruin.\n\nHelp rid the Dragonmaw of Mor'ghor, and those of us with pure blood will be your allies forever. This I can promise.", sourceObjective = "Return to Admiral Stonefist off the shore of Dragonmaw Hold in Twilight Highlands.", completion = "The Fel Orcs from Outland have laid claim to the Dragonmaw? Obscene!\n\nIf Hellscream knew what was happening here, he'd raze their city to the ground...", sourceObjectiveStatus = "unverified-source-field" }
quests[26609] = { id = 26609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving {race} {class} is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nWe've made Booty Bay our happy home away from the high seas, but word has it that the Bloodsail have some new plan cooked up.  All me boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", sourceObjective = "First Mate Crazz wants you to check the cove north of Booty Bay.", completion = "On top of the barrel, you discover a map with some hastily written text on it, along with some coins.", sourceObjectiveStatus = "unverified-source-field" }
quests[26610] = { id = 26610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodsail Treachery", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"Set up your command post here, and bide your time.  The Fleet Master will send out word when it's time to make your move.\"\n\n\"I'm placing Lieutenant Bruce in charge here.  This time will be different.  This time we take Booty Bay once and for all.\"\n\nThe map is held in place with a dagger, placed right through the location of Booty Bay.", sourceObjective = "Report your findings to First Mate Crazz in Booty Bay.", completion = "Sure, I remember you, {class}.  Back from scouting I see....", sourceObjectiveStatus = "unverified-source-field" }
quests[26611] = { id = 26611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baron Must Be Told", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Baron Revilgaz at once!  You'll find him here in Booty Bay.", sourceObjective = "Report the planned Bloodsail attack to Baron Revilgaz.", completion = "Bloodsail Buccaneers attacking Booty Bay?  This isn't the first time that those blaggards have tried something.  Booty Bay is impenetrable!\n\nSounds like they might be changing their strategies up, though.  Wouldn't put it past Firallon to try something crazy.  Very well, let's see what else they're up to.", sourceObjectiveStatus = "unverified-source-field" }
quests[26612] = { id = 26612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Details of the Attack", description = "I want to know details, {name}.  Our supremacy over the Bloodsail is due largely in part to our stronghold here in Booty Bay, but intelligence also plays a critical role.\n\nThe Bloodsail maintain a few meager camps to the south which they call their \"Southern Command.\"  Well, you're going to raid their excuse for a southern command, find their plans, and slaughter their men.  Return with whatever information you can find.", sourceObjective = "Kill 8 Bloodsail Sea Dogs and 8 Bloodsail Elder Magi, and bring back the Bloodsail Charts and the Bloodsail Orders.", progress = "Ahoy, {name}.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, {name}.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape....", sourceObjectiveStatus = "unverified-source-field" }
quests[26613] = { id = 26613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless {class} like you could convince 'em to share the goods, eh?", sourceObjective = "Deeg in Booty Bay wants you to bring him 15 tiny heaps of Snuff.", progress = "Any luck finding the goods, matey?", completion = "Good show, {name}!  And just before I need to ship out too!  Can't thank you enough, old friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[26614] = { id = 26614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", sourceObjective = "Retrieve Dizzy's Eye from the Bloodsail Buccaneers.", progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n<Kshhh-thunk>\n\n{name} ho!  Blimey, I can see!!", sourceObjectiveStatus = "unverified-source-field" }
quests[26616] = { id = 26616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Never Over", description = "Those Blackrock orcs are gonna need an army to handle the Bravo Company and you, {name}. When you're ready to go, meet us at the dock facing Lake Everstill and we'll set off on my riverboat for Camp Everstill on the other side of the lake.\n\nSee you there, {name}.", sourceObjective = "Take Keeshan's Riverboat to Camp Everstill in Redridge.", completion = "It's orc killin' time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26617] = { id = 26617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Sea Dog", description = "This old, weathered coin was found on the body of the pirate \"Good-Boy\" Bruce.  Its front side bears the image of a large, unfamiliar pirate ship; on its back side, the term \"Brashtide Crew\".\n\nSomeone who has been in the piracy business for some time might know what this coin is, or what it means.", sourceObjective = "Bring the Weather-Beaten Coin to Fleet Master Seahorn in Booty Bay.", progress = "What's that you've got there, {race}?  Let me see it.", completion = "That coin!  Where did you get it?\n\nBruce... yes, I see.  He was one of the Blackwater Raiders once.  One of us, before Greymane closed the Gilneas ports and held his crew captive.\n\nI know that what happened in Gilneas changed the people there, but I never expected them to change their loyalties.  Especially not Bruce.\n\nIf you wouldn't mind, could I keep the coin?  I'll pay its worth in gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[26618] = { id = 26618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolves at Our Heels", description = "The dire wolves are the most common threat to the townsfolk here. They lurk in the forests on all sides of us, though most are along the north bank of the river.\n\nThese aren't the runt dogs you see in Elwynn, or wherever you come from. They're big as a man and twice as vicious.\n\nIf you wish to assist the people of Darkshire, hunt the dire wolves so our streets can be safer.", sourceObjective = "Kill 12 Dire Wolves.", progress = "You still hunting wolves...?", completion = "Don't go thinking that was too easy. Far greater dangers lurk deeper in the woods.", sourceObjectiveStatus = "unverified-source-field" }
quests[26619] = { id = 26619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Say You Want a Revolution", description = "If what you say is true, {name}, then we have friends within the Dragonmaw Clan. We can support an insurgency from within their ranks and avoid a lot of bloodshed on both sides.\n\nI can help, but the most dangerous part is up to you.\n\nMy Axebite Warriors will launch an offensive on the shores. During the confusion, I need you to slip behind the lines and speak with your revolutionary contact, Zaela.\n\nWe'll arm the Dragonmaw and overthrow their fel masters!", sourceObjective = "Slip through the front lines at Dragonmaw Port and speak with Zaela.", completion = "{name}, what are your people doing? Are you attacking the Dragonmaw or are you here to rid us of Mor'ghor's corruption?\n\n\n\nAh, I see now. I like the way you think. Warchief Mor'ghor won't even know what hit him.\n\nLet's do this!", sourceObjectiveStatus = "unverified-source-field" }
quests[26620] = { id = 26620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seasoned Wolf Kabobs", description = "Seasoned wolf kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.\n\nBring me five wolf skirt steaks.  The dire wolves near the river north of town are good to hunt; I wouldn't stray too far into the woods if I were you.", sourceObjective = "Gather 5 Wolf Skirt Steaks from Dire Wolves.", progress = "Were you able to find five wolf skirt steaks yet?", completion = "Mmm-mmm! The skirtsteak's the best part. It's not an efficient way to cook, though.\n\nHere, have this recipe. It's a little different, but flank meat's easier to come by when you really need a meal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26621] = { id = 26621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insurrection", description = "The weapons the Horde has supplied us with will be more than enough. The four of us should split up and arm as many Dragonmaw workers and merchants as we can.\n\nDon't underestimate us, {name}. You'll find even our tradesmen are ferocious in battle.\n\nLet's do as much damage as possible. Arm a squad of Dragonmaw and lay waste to the fel enforcers and warlocks that have intimidated my people for so long. Then meet back here to launch our final strike!", sourceObjective = "Arm 3 Dragonmaw Workers or Merchants, then slay 10 Dragonmaw Enforcers and 4 Dragonmaw Warlocks.", progress = "Revolution, at last!\n\nThe Dragonmaw are finally undoing the shackles of the filth who have held us back!", completion = "We've lost a lot of good orcs, but the fight is going our way, {name}.\n\nMor'ghor's regime is collapsing. All that remains is to destroy the beast himself.", sourceObjectiveStatus = "unverified-source-field" }
quests[26622] = { id = 26622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Mor'ghor", description = "The time has come. Mor'ghor dies today.\n\nBe warned, {class}. Demon blood courses through his wretched veins, and he channels unnatural power. He will be destroyed, yes. But it will not be an easy fight.\n\nYou remember where Mor'ghor resides, at the top of the camp. I will meet you there. Finish him!\n\nBe sure to recruit 3 Dragonmaw followers if you are short - you will need our help.", sourceObjective = "Slay Warchief Mor'ghor in Dragonmaw Port. You can still recruit Dragonmaw Merchants and Workers to help you.", completion = "Well done, {name}! You have done the Horde proud in my absence.\n\nThe Dragonmaw have joined us, with Zaela as their new leader. Blood was shed, but casualties were low, and we have their complete loyalty.\n\nOur Horde grows stronger!", sourceObjectiveStatus = "unverified-source-field" }
quests[26623] = { id = 26623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider meat!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!\n\nIf you want to try some still, I'm afraid I'm out of meat. I need some lump meat to whip up a few more cakes.\n\nVenom Web Spiders are a good source - they nest to the north, between the foothills and the river.", sourceObjective = "Gather 6 Dusky Lumps from Venom Web Spiders.", progress = "Hail, {name}.  Did you get that lump meat for me?", completion = "Ah yes, a nice lump you have there!  Let me just get this seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good.", sourceObjectiveStatus = "unverified-source-field" }
quests[26624] = { id = 26624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting In With the Bloodsail", description = "These plans are... interesting.  Firallon, you're smarter than this!\n\nLook, he has all three ships devoted to cannon fire, and only a few men coming in through the tunnel.  He can never take Booty Bay with three ships and a dozen footmen.  And he knows that.\n\nNo, they've got something else planned... and you're going to find out what it is.  Speak to Yancey Grillsen, the Bloodsail Recruiter, just to the north of town.\n\nThat's right, {name}.  You'd better hope that they don't recognize your face.", sourceObjective = "Report to Yancey Grillsen at the waterfall north of Booty Bay.", completion = "Yarr, ya made a good decision, lad.", sourceObjectiveStatus = "unverified-source-field" }
quests[26625] = { id = 26625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggzor the Earthinator", description = "You have to put an end to this now!\n\nGo back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.", sourceObjective = "Obtain the Earthinator's Cudgel.", progress = "Is he dead? Do you have the cudgel?", completion = "<Gravel solemnly nods his head.>\n\nFinally, we can move forward and rescue the Stonefather.", sourceObjectiveStatus = "unverified-source-field" }
quests[26627] = { id = 26627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit", description = "I've been told there's signs of activity at Beggar's Haunt. People have reported seeing lights in the tower to the east of town.\n\nFew would be bold enough to stay that close to Deadwind Pass. You're the first to report since I've learned about this; go check it out and make sure whatever's in there is human.", sourceObjective = "Find the denizen of the tower at Beggar's Haunt.", completion = "Ah, welcome, stranger. I'd offer you something, but there's not much here...\n\nCould I beg you to run some errands for a poor old hermit?", sourceObjectiveStatus = "unverified-source-field" }
quests[26628] = { id = 26628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, {name}?", sourceObjective = "Protect Shakes O'Breen during the attack.", completion = "We survived the attack!\n\nWe could not have done it without you, {name}.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny {race}....", sourceObjectiveStatus = "unverified-source-field" }
quests[26629] = { id = 26629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Where Your Loyalties Lie", description = "Thar be just one thing...\n\nYancey hears things.  A few o' me hearties were pretty deep in their cups when they told me about some {race} {class} that came a-rollin' through the Southern Command lookin' for charts and orders.  Even ran a couple o' good pirates through, <he/she> did.\n\nLike I said, they were up to their eyeballs in grog, but still... a buccaneer's gotta trust his ears.  So I've just got one small task for ye, one sent down from Firallon hisself...\n\nBring me the head of Fleet Master Seahorn.", sourceObjective = "Obtain the Head of Fleet Master Seahorn in Booty Bay.", progress = "Firallon special-ordered this one himself.  Said the tauren's too much of a risk.", completion = "Well blow me down!  Now there's something ya don't see too often.\n\n<Yancey reaches out and shakes your hand.>\n\nWelcome aboard, {name}.  Plunder and booty await ye.", sourceObjectiveStatus = "unverified-source-field" }
quests[26630] = { id = 26630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looks Like a Tauren Pirate to Me", description = "Firallon wants MY head?  Now that's interesting.  But it's nothing we can't work around.\n\nThis Yancey character probably doesn't know my face too well.  Most non-tauren find us tauren indistinguishable from one another.  In fact... most non-tauren find us indistinguishable from... a certain four-legged farm creature.\n\nRikqiz the leatherworker keeps one of these creatures here in Booty Bay, and Narkk is my chief supplier for pirate hats.  Get a replacement head and a hat, then return with both.", sourceObjective = "Obtain a Cow Head and an Oversized Pirate Hat, then bring them back to Fleet Master Seahorn.", progress = "You should know that most tauren would find this shameful.  I find it... amusing.", completion = "That should fool that Bloodsail dimwit.\n\nThis was fun, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26631] = { id = 26631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Day as a Pirate", description = "Ye may be a slayer of Fleet Masters, but rules is rules and orders is orders.  And MY orders say that all new pirates start out as swabbies.  It's the rule.\n\nYou're to be working for Captain Keelhaul, the commander of the Riptide.  It's the westernmost ship in the fleet, which is parked south of the tip o' the cape.\n\nFind him in his captain's chambers, and bring yer papers.", sourceObjective = "Bring Yer Papers to Captain Keelhaul.", progress = "I trust y'got yer papers, swabbie.  I'd hate t'send ye all the way back to Yancey.", completion = "Yes... yes... I see... well, everything appears to be in order.\n\nSlayer of the great Seahorn, eh?  That doesn't matter on MY ship.  Only thing you're gonna be slaying is deck stains.  Grab a mop.", sourceObjectiveStatus = "unverified-source-field" }
quests[26632] = { id = 26632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Escort", description = "Alright, I think I've got it working again. You've got to get the catapult to the stone trogg town, Needlerock Slag, just to the north of the front.\n\nThe driver will go with you. I'll head back and let Gravel know.\n\nThere's no doubt that the stone troggs will try to stop you. You just keep them off of the catapult. It packs a big punch.\n\nLet me know when you're ready, {name}.", sourceObjective = "Escort the Earthen Catapult safely to Needlerock Slag.", completion = "<The catapult chief gives you an appraising look.>\n\nWord of your prowess has spread ahead of you, {race}. Let's see if you can help us keep these fungal horrors off of the front.", sourceObjectiveStatus = "unverified-source-field" }
quests[26633] = { id = 26633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swabbing Duty", description = "I want the surface of the Riptide t'shine like a star ruby, Swabbie {name}.  I keep a tight ship around here, and it's swabbies like you that make it happen!\n\nWell, what're y'waitin' for, y'cockle-brained bilgerat?  Head updecks and start swabbin'!", sourceObjective = "Pick up a Swabbie's Mop on the deck of the Riptide, then keep the deck clean for 2 minutes.", progress = "Y'try my patience, swabbie.  Yer this close t'gettin' kicked back OUT o' the pirates.", completion = "I heard the most furious mopping sounds from down here, mate.  That's EXACTLY what your Captain likes to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[26634] = { id = 26634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bane of Many A Pirate", description = "Gum disease.  It's a real problem, {race}.\n\nI know you're new and all, and probably haven't ever needed your gums cut, but the rest of us pirates have to deal with a little thing called SCURVY.  It's why we keep so many limes around here.\n\nWell... we used to keep limes around here.  Someone made off with our last shipment, but they can't have gone far - maybe to the nearby islands?  Bring them back, and maybe I'll see what I can do to get you promoted from swabbie.", sourceObjective = "Obtain 5 Bushels of Limes.", progress = "I've seen too many good men die to such a preventable disease, {race}.  We need those limes.", completion = "I'll distribute these right away, {race}.  And I'll see what I can do to put in the good word for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26635] = { id = 26635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball Swim", description = "Help out a fellow swabbie?\n\nKeelhaul asked me to gather up some cannonballs at the bottom of the ocean.  Let me tell you why this doesn't work for me.\n\n- One: I have tiny arms.  Look at them!  Do you really think I can pick up a cannonball, even underwater?\n\n- Two: I have a weak respiratory system.  I start to white out after holding my breath for more than ten seconds.\n\n- Three: There are sharks.\n\nYou gotta help me, {name}!  I've been demoted as far as I can... I don't want to see what comes next!", sourceObjective = "Obtain 6 Bloodsail Cannonballs from the water beneath the Riptide.", progress = "I wasn't always a swabbie, you know.", completion = "Thanks, {name}.  I'd been hearing whispers about \"Pretty Boy\" and a \"boo-box\".  I don't think I want to go in the boo-box.", sourceObjectiveStatus = "unverified-source-field" }
quests[26636] = { id = 26636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bravo Company Field Kit: Camouflage", description = "We're gonna need some supplies before we take out the Blackrock army and save Redridge. That's where you come in, rookie.\n\nKeeshan put me in charge of getting camouflage together for the Bravo Company field kit. What I need you to do is head south and do a little \"gardening.\" There are two parts to this little adventure that you should know about: (1) Leaves and (2) Fox poop. We need 'em both.\n\nWhat did you think camo was made of?\n\nHead south and gather what I asked for, <pal/lady>.", sourceObjective = "Gather 5 Piles of Leaves and 5 pieces of Fox Poop.", progress = "Leaves and poop - that's what I need.", completion = "Nice job, rookie. I'm gonna go ahead and put the camo in the box. We should be ready soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26637] = { id = 26637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bravo Company Field Kit: Chloroform", description = "The first part of this mission is all covert ops, {name}. To that end, we need to be able to incapacitate the enemy without making any sounds. To do that we're going to need chloroform.\n\nThe muckdwellers at the bottom of Lake Everstill hold chloroform in their glands. I'm going to need you to go underwater and recover muckdweller glands. Think you can handle it?\n\nCome back to me once you've recovered enough glands.\n\nWhere's the lake you ask? Open your eyes, dummy. Directly west.", sourceObjective = "Collect 8 Muckdweller Glands.", progress = "Did you recover the glands?", completion = "Perfect. Those orcs won't know what hit 'em - literally. I'll need a few minutes to get these in working order and then I'll put them in the Bravo Company field kit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26638] = { id = 26638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Hunters", description = "Just south of here on the Lakeridge Highway are a group of Blackrock orcs that stalk the forests under cover of darkness and ambush the uninitiated. That group is the first line of defense for the Blackrock army. They're scouts, reporting everything they see back to their central command. They need to be taken OUT or our mission here could be compromised.\n\nHead south and kill every Blackrock hunter that you see.", sourceObjective = "Kill 8 Blackrock Hunters.", completion = "Great work, {name}. We need to move quickly before they send for reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[26639] = { id = 26639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Point of Contact: Brubaker", description = "Before we do a damned thing we need to get a field kit together. You'll help with that, {name}. There's also a matter of scouting. Thankfully for that we got some help from Stormwind. An old war buddy of mine, Brubaker, was sent here by SI:7 to scout around for us. You're to meet him in the field, just south of here.\n\nMeet up with Brubaker and find out what he knows.", sourceObjective = "Find Brubaker.", completion = "Brubaker is dead. It looks like the orcs are attempting to send a message with this grisly display. Upon closer examination you notice something in Brubaker's pouch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26640] = { id = 26640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unspeakable Atrocities", description = "<You unfold the note and begin reading.>\n\nKeeshan, if you're reading this note, I'm dead. Likely that my position was compromised.\n\nOrcs are committing unspeakable atrocities against their prisoners. Yes, prisoners, Keeshan. They've got cages full of P.O.W's. If you're gonna blow up this valley, you'll need to free the prisoners first.\n\nTell my wife I love her and to take out the damned trash.\n\n-Brubaker\n\nPS - They've got black dragons.\n\nTake Brubaker's report back to Keeshan.", sourceObjective = "Deliver Brubaker's Report to John J. Keeshan at Camp Everstill in Redridge.", progress = "They got Brubaker?", completion = "<Keeshan reads the report.>\n\nDAMN IT! This just got complicated. We've got prisoners of war to rescue before we can blow up the valley. Not to mention the orcs have black dragons on their side.\n\nAre you ready, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26641] = { id = 26641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Make An Omelette Without...", description = "The Vilebranch broodguards to the northeast tend the eggs of Shadra's brood. Even if we kill the Vilebranch, those eggs will still sit there, waiting to hatch and release those horrible creatures further into the wilds.\n\nWe need to take care of this properly. Tear any eggs you see out of the egg sacks and bring them to me. Don't try to destroy them on your own; you might let the little ones out.\n\nWhen you get them back here, I'll see that they're properly disposed of!", sourceObjective = "Collect 5 Shadraspawn Eggs from Agol'watha.", progress = "Do you have the eggs?", completion = "I'll see these are burnt to ash right away, and scattered to the winds for good measure.", sourceObjectiveStatus = "unverified-source-field" }
quests[26642] = { id = 26642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Barrens", description = "For years, the Barrens have been the heart of the Horde presence on Kalimdor, a vital link between the orcs of Durotar and the tauren settlements in Mulgore.\n\nIn the chaos of the cataclysm, floods, earthquakes, and even a quilboar invasion threaten to separate us from this vital grassland.\n\nYou look ready for a challenge. Report to Kargal Battlescar at Far Watch Post and ensure the route to the Barrens remains clear! Head west from nearby Razor Hill and cross the Southfury River to find him.", sourceObjective = "Report to Kargal Battlescar at Far Watch Post in Northern Barrens.", completion = "A fresh recruit from Orgrimmar is it?\n\n<Kargal sizes you up.>\n\nI'll take what I can get. Keeping the roads open has been a nightmare.", sourceObjectiveStatus = "unverified-source-field" }
quests[26643] = { id = 26643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starvation Diet", description = "The Creeping Ruin to the east is crawling with fully-grown Shadraspawn spiders. They're large enough to drag off an entire dwarf in the night, and you'll see evidence enough of that when you get there... bodies are cocooned all through the ruins.\n\nThey don't keep them alive for long, {name}, but they feed off the bodies for days. It's too late to save the victims, but we can't let those spiders grow fat and thrive. Make sure you get rid of those cocoons.", sourceObjective = "Destroy 6 Cocooned Victims at the Creeping Ruins.", completion = "A grim task for sure, {name}, but it'll keep the spiders left alive from recovering. I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26644] = { id = 26644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attracting Attention", description = "Swabbie {name}!  This is a sad day fer ol' Cap'n Keelhaul.  Today I lose m'best swabbie.\n\nA letter's come in from Fleet Master Firallon.  Apparently he's heard about the excellent swabbin' y'been doin', and he wants t'take ye aboard the Crimson Veil as his Jack o' Swords and third mate.  She's moored just next t'the Riptide.\n\nPiracy career-wise, this's a big step fer ye, Swabbie {name}.  I recommend y'take his offer.\n\nDismissed!", sourceObjective = "Report to Fleet Master Firallon within the Crimson Veil in the Cape of Stranglethorn.", completion = "So ye be the one that did ol' Seahorn?  Yancey sent word, but I wanted to make sure he hadn't been telling his tall tales again.\n\nI'll make it brief.  Ye did well on Keelhaul's crew, but I expect ye to do even better on mine.  I've got an entire fleet to attend to, so you'll be helpin' to run the day-to-day of me ship.\n\nWelcome aboard the Crimson Veil, sailor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26645] = { id = 26645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Night Watch", description = "I'm afraid you're all I've got to help here, {name}. Stormwind's forces are so taxed by greater evils that they can't spare a single footman to protect Darkshire. It's up to me and the rest of the Night Watch to keep our homes safe.\n\nThere's more threats here than just wolves, unfortunately. Rotting horrors roam near Blind Mary's Haunt, on the southeast outskirts. If they're not kept in check, they'll be visiting our homes in the night.\n\nDeal with the undead and report back to me for your bounty.", sourceObjective = "Kill 8 Rotting Horrors near Blind Mary's Haunt, southeast of Darkshire.", completion = "Splendid, {name}.  For your service to the people of Darkshire you shall be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[26646] = { id = 26646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of War", description = "The Bravo Company field kit is ready, {name}. I'm gonna equip you with it and you're gonna enter Render's Valley, southeast of here, and free our P.O.W.s.  I'm sending Jorgensen with you to watch your back.\n\nNow the prisoners are being held on the northeast side of the valley in a large cage, but the key to the cage is in a cave on the south side of the valley. You'll have to steal the key, create a distraction, and free the citizens.\n\nGood luck, {name}! I'll be in touch through the field kit.", sourceObjective = "Free the Prisoners of War locked up in the prison at Render's Valley.", completion = "<The radio on the Bravo Company field kit crackles.>\n\nLooks like the P.O.W.s are free. Time to initiate Operation: End All.", sourceObjectiveStatus = "unverified-source-field" }
quests[26647] = { id = 26647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ol' Blasty", description = "We've got some work to do.  How much experience have you got with cannons?  Hmm... really?  Well, how about with ancient, fallin'-apart pirate cannons?\n\nWe've got a few cannons updecks that work the old-fashioned way: you load one cannonball in at a time, aim, lock it into place, and fire.  Works well if you're tryin' to hit the side of a three-sailer... not so well for rowboats and the like.\n\nWhy don't you head upstairs and lob a few shots at Smilin' Timmy Sticks?", sourceObjective = "Practice using the cannon by hitting Smilin' Timmy Sticks 5 times with cannonballs from Ol' Blasty.", completion = "I like the cut of your gib, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26648] = { id = 26648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Mortal Enemies", description = "Hey, new <guy/girl>, take a look at this.\n\n<The dwarf flips up his eyepatch to reveal a living, functional eyeball.>\n\nI don't wear this patch because of any lost eye.  I wear it because this OTHER eye is so strong, the normal one was just weighin' it down.\n\nThis eye's good for seein' all kinds of things, like those masked hooligans that follow us around.  Fleet Master says that they've been spotted over on Jaguero Isle.  Once you get there, fire this flare gun, and I'll help you spot 'em.", sourceObjective = "Kill 15 Ninjas on Jaguero Isle.", completion = "Excellent work, {name}.  The eternal battle wages on, but we've tipped the scales in favor of the pirates today.  Firallon will be happy to hear the news.", sourceObjectiveStatus = "unverified-source-field" }
quests[26649] = { id = 26649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive-By Piracy", description = "Now that you know how to handle our cannons, it's time to hit some real targets!\n\nThe Venture Company has found gold to the north of here... a rare type they call \"Black Gold\".  More like a Black Spot if you ask me.\n\nWe're going to take that gold, but first, we need to get rid of those Venture Company goons.  I've got an oarsman who will take you out there.  Head off the ship down the gangplank and speak with him on the islet's northern shore.", sourceObjective = "Speak with the Bloodsail Oarsman outside the Crimson Veil, then use the cannon to kill 75 Venture Co. Oil Workers.", progress = "Those goblins will learn the fury of the Bloodsail!", completion = "Ahahaha!  Blasted 'em clear off their rigging!  I'll drink to that!\n\nYou've got a bright future, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26650] = { id = 26650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damsel's Luck", description = "I know ye just arrived here on the Crimson Veil, but I need to send ye off on another task.  The Damsel's Luck is the third ship in me fleet, moored over to the east.  Her skipper - Captain Stillwater - is no longer with us.\n\nDamn those masked hoodlums!\n\nAnyhow, Ironpatch told me about yer heroics at sea, and I be runnin' low on quality brigands.  I think yer more than capable for this new duty.\n\nCongratulations, matey.  Ye be the new captain of the Damsel's Luck.", sourceObjective = "Report to your Captain's Chambers within the Damsel's Luck in the Cape of Stranglethorn.", completion = "You see a set of plans unrolled on the table.  They explain everything!\n\nThese are the details of the impending attack on Booty Bay.  Battle formations, plans of attack, and something about a group called the \"Brashtide Crew\".", sourceObjectiveStatus = "unverified-source-field" }
quests[26651] = { id = 26651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Win a War, You Gotta Become War", description = "<The Bravo Company radio beeps.>\n\nDo you understand yet, {name}? Do you now see what we gotta do to win a war against these monsters? YOU GOTTA BECOME WAR! NO MERCY!\n\nWith the P.O.W.s freed you're clear to plant the seaforium. Carefully make your way into each of the structures out there and plant a charge.\n\nPlant a seaforium charge at the Blackrock munitions hut and the Blackrock tower. Once you're done meet up with me and the rest of Bravo Company at Shalewind Canyon, east of Render's Valley.", sourceObjective = "Use the Bravo Company Field Kit to plant a Seaforium Charge at the Blackrock Tower and Blackrock Munitions Hut.", completion = "And now, we blow the whole damned thing up.", sourceObjectiveStatus = "unverified-source-field" }
quests[26652] = { id = 26652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", sourceObjective = "Bring the Spectral Comb to Blind Mary.", progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror...", sourceObjectiveStatus = "unverified-source-field" }
quests[26653] = { id = 26653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some ghost hair thread?  You can get it from Madame Eva at her home on the Darkshire square.", sourceObjective = "Speak with Madame Eva in Darkshire.", completion = "Ah, ghost hair thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair.", sourceObjectiveStatus = "unverified-source-field" }
quests[26654] = { id = 26654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", sourceObjective = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", progress = "I sense that you have seen Blind Mary.  You have my comb...?", completion = "I can make a spool of ghost hair thread with this, and have a few strands to spare.  Here are some coins for those extra strands.", sourceObjectiveStatus = "unverified-source-field" }
quests[26655] = { id = 26655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Thread", description = "Here is your thread, {name}.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", sourceObjective = "Bring the Ghost Hair Thread to Abercrombie in his tower at Beggar's Haunt.", progress = "I need to string the ghost hair thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good {name}, take this as payment for your honorable deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26656] = { id = 26656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't. Stop. Moving.", description = "When Deathwing came, the Stone Dragons flocked to him. In his absence, they are again without purpose. They swarm and feed upon our kin.\n\nI have bound dozens of Opalescent Guardians, but am unable to lead them from the safety of cover. I need someone more swift, as I suspect you might be.\n\nLead them by ground towards Therazane's Throne to the east. Surely, some will not make it, but as long as you keep moving, you should be able to bring several to join our forces there.", sourceObjective = "Rush at least 5 Opalescent Guardians east by ground, out of the Pale Roost, to the stone circle near Therazane's Throne.", progress = "Did they make it, {class}?", completion = "Well done. Of my main strengths, speed is not one.", sourceObjectiveStatus = "unverified-source-field" }
quests[26657] = { id = 26657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Falls", description = "Stone Dragons bow only to strength. When we have punished them enough, they will bend back to our will.\n\nI have sent many of my strongest giants onto the fields in the west. They will bring the drakes to the ground. You will see to it that they do not take wing again after they fall.", sourceObjective = "Kill 6 Stone Drakes.", progress = "Look to the dragons that have been knocked out of the sky by boulders. They will be easier targets.", completion = "Not just fast it seems. You have some bite in you.\n\nWell done, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26658] = { id = 26658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragile Values", description = "It is now time to draw the Broodmother's attention. To do so, we will need a mallet that the troggs use when making offerings to her.\n\nSeek out the Stone Trogg Beast Tamers that are attempting to tame basilisks in the southern portions of the Pale Roost. You will find a mallet on one of their corpses.", sourceObjective = "Retrieve a Stonework Mallet.", progress = "Did you find a mallet?", completion = "Glorious.\n\nNow we will deal a blow to the stone dragons that they will remember for the next hundred years.", sourceObjectiveStatus = "unverified-source-field" }
quests[26659] = { id = 26659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonating Blow", description = "On the western edge of the Pale Roost, you will find a resonating crystal. Strike it with the mallet and the broodmother will come.\n\nBe ready for battle. I will be there to aid you, but she will not be easily overcome.", sourceObjective = "Defeat Aeosera.", progress = "This broodmother has taken wing over these stone drakes for nearly 300 years. She is quite strong, even for a stone dragon.", completion = "Impressive, fleshling. You are far more capable than I initially assumed.\n\nI will extend that sentiment to the Stonemother as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26660] = { id = 26660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, {name}.  These nights get cold, and I need that drink to put fire in my veins again!", sourceObjective = "Speak with Tavernkeep Smitts.", completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26661] = { id = 26661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nrot blossoms grow in strange places.  They tend to flourish on dead things, and Duskwood has its fair share of those!\n\nI've seen a few of them growing at Tranquil Gardens Cemetery lately. Check near the graves... but mind the dead that are walking about near there.", sourceObjective = "Gather 5 Rot Blossoms from Tranquil Gardens Cemetery.", progress = "Hi, {name}.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.\n\nI'll whip up the zombie juice... it's strong stuff, I warn you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26662] = { id = 26662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brashtide Crew", description = "The charts mention a group called the Brashtide Crew.  This name is new to you, though you've heard about a few other newcomers to the Buccaneers.\n\nMaybe it's time you paid them a visit and found out what they know.", sourceObjective = "Speak with Long John Copper on the Damsel's Luck, Enormous Shawn Stooker on the Crimson Veil, and Wailing Mary Smitts on the Riptide.", progress = "The details here are sparse.  You'll need to find some other members of the Brashtide Crew if you want information.", completion = "The Brashtide Crew aren't just pirates... they're worgen pirates!  And they're joining in on the attack!\n\nRevilgaz is definitely going to want to know about this.", sourceObjectiveStatus = "unverified-source-field" }
quests[26663] = { id = 26663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinking From Within", description = "The attack on Booty Bay is looming.  You'll have to return to Booty Bay quickly and inform the Baron.\n\nFirst, however, it might be a good idea to sabotage some of the pirates' supplies while you're still in their favor.  The pirates keep most of their supplies belowdecks, spread out across the entire fleet.", sourceObjective = "Sabotage the Barrel of Grog, the Barrel of Gunpowder, and the Crate of Cannonballs.", completion = "You've set the pirates back several days' work.  Hopefully this will delay their attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[26664] = { id = 26664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Mutiny", description = "Before returning to Booty Bay, you should do everything you can to weaken the Bloodsail Buccaneers.  Unfortunately, even as captain, you're prohibited from killing other buccaneers in cold blood.  Only a Fleet Master can do that.\n\nYou can, however, put mutineers to the sword... and mutiny can be awfully hard to disprove.\n\nSpeaking of which, those Bloodsail corsairs that hang out on the lowest level of the ships have been acting awfully suspicious...", sourceObjective = "Accuse 9 Bloodsail Corsairs of mutiny, then kill them.", completion = "The fewer Bloodsail Buccaneers that Booty Bay has to fight, the better.  However, it might be best to stop slaughtering your supposed allies before you draw suspicion to yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[26665] = { id = 26665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Booty", description = "You feel like you've done just about enough damage, and you know the Bloodsail's battle plans.  You've done everything that Baron Revilgaz has asked of you.\n\nIt's time to hang up the pirate hat and return to Booty Bay.  The battle looms near.", sourceObjective = "Report to Baron Revilgaz at Booty Bay in the Cape of Stranglethorn.", completion = "The Brashtide!?  I thought they were dead and gone YEARS ago!\n\n<Revilgaz listens intently as you relay the information you gathered.>\n\nNo, that absolutely makes sense.  And it's not good news either.  The Brashtide are formidable foes, and if their numbers are anywhere near what they were before they disappeared, we're in for a nasty battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[26666] = { id = 26666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "I'm here because I received a letter from my brother Stalvan, who I haven't seen in years. On arriving here, I was told he was dead...\n\nThe entire town refuses to offer any further explanation. Any mention of his name is met with terror and suspicion. As if I didn't have enough of that myself!\n\nI'm afraid of what will happen if my frustration and anger grows any further. I beg you, help me get to the bottom of this. Implore Clerk Daltry for any information he may have on my brother.", sourceObjective = "Seek out Clerk Daltry in the Darkshire Town Hall.", completion = "Can I help you?", sourceObjectiveStatus = "unverified-source-field" }
quests[26667] = { id = 26667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Letters", description = "You want to know about Stalvan...\n\nYou're not the first, you know. We get outsiders coming through asking about him every so often. Always outsiders. Everyone who lives here knows better.\n\nYou're out of luck, anyway. I'm missing half the archives. Feral worgen broke into the town hall not a few nights ago and tore the place to shreds.\n\nThe documents you'll want are probably strewn all across Brightwood Grove by now, deep in the woods to the west. Not worth it if you ask me.", sourceObjective = "Collect the Bundle of Shredded Letters from Brightwood Grove.", progress = "Look, sir, I really don't want any trouble...", completion = "By the Light... you actually went and got it?\n\nI'm shocked. I suppose I owe you thanks for returning it to the archives.", sourceObjectiveStatus = "unverified-source-field" }
quests[26668] = { id = 26668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation", description = "Those explosives you planted were high yield, {name}. When I push this button on the Bravo Company field kit, that whole valley is gonna be consumed by a massive fireball of death.\n\nYou know, I think you should do the honors. You did all the hard work, after all.\n\nReady?", sourceObjective = "Blow up Render's Valley.", completion = "Did you see those orcs explode? THAT'S HOW WE DO IT IN BRAVO COMPANY! Now to clean up the rest of these jackasses.", sourceObjectiveStatus = "unverified-source-field" }
quests[26669] = { id = 26669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In A Dark Corner", description = "If you're that serious about this, I'll help you, {name}. I know where the other documents must be. I'm just too terrified to do anything about it.\n\nThere's only a few places that those horrible Nightbane beasts gather when they're not prowling the forest. One of them's the Rotting Orchard to the south. They use the buildings there as their dens, so if they haven't just eaten the other documents, you might find one there... but you'll have to search their lairs thoroughly, I wager.", sourceObjective = "Search the Rotting Orchard for the Torn Journal Page.", progress = "You're back in one piece, I see.", completion = "This was all you found?\n\nThat's bad news, I'm afraid...", sourceObjectiveStatus = "unverified-source-field" }
quests[26670] = { id = 26670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roland's Doom", description = "This isn't all of it...\n\nYou should let it go, {name}. The only place left to look is Roland's Doom. That's the mine south of town, and the largest lair of worgen in Duskwood. Nobody in Darkshire has ever made it back from that place alive. In fact, some of the records I have here imply that's where the monsters first came from... who knows what evil's lurking in there?\n\nPlease, {name}, just give it up. Let's just forget about this whole thing, and never speak of it again.", sourceObjective = "Search Roland's Doom for the remaining pages of Stalvan's Journal.", progress = "I told you, {name}, it's not worth pursuing...", completion = "You actually went and got it?!\n\nI don't know whether to call you brave or insane. But once again, my archives thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26671] = { id = 26671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Stalvan Mistmantle", description = "You've recovered everything. Everything except the last page...\n\n...which I've got right here. Don't look at me like that. You'll understand when you read it. Some even say it's cursed, you know. In fact, I was relieved when the worgen broke in and made off with these!\n\nTake it. Take all of it, in fact. I thank you for recovering my archives, but I don't want anything to do with this ever again. Please, just leave me be.", sourceObjective = "Take The Legend of Stalvan back to Tobias Mistmantle.", progress = "You're back! Did you find anything about my brother?", completion = "I can't thank you enough... I had hoped for this to be a joyous reunion, but the more I learn, the less glad I am to have asked.\n\nBut I must know.", sourceObjectiveStatus = "unverified-source-field" }
quests[26672] = { id = 26672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clawing at the Truth", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>\n\nI must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, {name}. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.", sourceObjective = "Bring the Mistmantle Family Ring to Madame Eva.", progress = "What dark whispers guide you to my door, {class}?", completion = "How interesting. It's been quite a while since I've seen such a ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[26673] = { id = 26673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BREADCRUMB", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>I must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, {name}. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.", sourceObjective = "Bring the Mistmantle Family Ring to Madame Eva.", sourceObjectiveStatus = "unverified-source-field" }
quests[26674] = { id = 26674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistmantle's Revenge", description = "I'm afraid I cannot give Tobias the answers he seeks. But I can help you find the only person who can...\n\nStalvan Mistmantle.\n\nTake the ring into the woods to the east, to Manor Mistmantle, where Stalvan's body was buried. Enter, and hold the ring before you. Let the waning moon pour its light through the ring, and the spirits will answer your call.\n\nTake heed, {name}. The questions of the living can offer more comfort than the answers of the dead.", sourceObjective = "Use the Mistmantle Family Ring at Manor Mistmantle, east of town.", completion = "Master Harris may have been right. I would have been better to leave the past behind.\n\nI've got a new life now. Whether it's that of a monster or a man is up to me.\n\nAs for you, I cannot thank you enough for your assistance, regardless of the outcome. Please, take this with my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26675] = { id = 26675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Value of Trust", description = "The troubles of this world seem to never fade. They shift, change, and reform, but they are ever-present.\n\nThe wind brought us whispers of a traitor in our midst. We sent one of our best sentinels to investigate, and now she has turned up dead. I did her disservice in assuming that the traitor would not be aware of our movements... I was brash, and she paid for my folly.\n\nI need a new face to pick up the trail. Someone the people of the city won't know. This is a dangerous request. Will you help me?" }
quests[26676] = { id = 26676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", sourceObjective = "Bring the Zombie Juice to Abercrombie at Beggar's Haunt.", progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, {name}.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[26677] = { id = 26677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghoulish Effigy", description = "Out here on the outskirts of town, it's a wonder the walking dead haven't eaten me!  In fact, just yesterday a pack of ghouls was pounding on the walls of my tower!\n\nI want to make an effigy - a kind of \"scarecrow\" for ghouls.  To do that I need some ghoul ribs.  You can find plenty of them on the fetid corpses wandering Manor Mistmantle's grounds, north of Darkshire...\n\nGet the ribs for me, and I will repay you with some coin.", sourceObjective = "Gather 7 Ghoul Ribs from Fetid Corpses at Manor Mistmantle.", progress = "I'm sure you could find plenty of ribs in Raven Hill as well, but you might not want to wander so far at night...", completion = "Ah, thanks.  These will do just the trick!", sourceObjectiveStatus = "unverified-source-field" }
quests[26678] = { id = 26678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doublerum", description = "<Baron Revilgaz sighs.>  Even with all my suspicions about Firallon's plot, we aren't prepared for a full two-front attack between the Bloodsail and the Brashtide.  It's going to take a small miracle to hold Booty Bay today.\n\nI've got a barrel of Doublerum in my chambers.  Take the stairs down three flights, and check the first door on your right.  You can ignore the warnings on the barrel... those should be the least of your worries.", sourceObjective = "Find Baron Revilgaz's Barrel of Doublerum within Booty Bay.", completion = "This must be the doublerum.  You pour a glass for Revilgaz, then consider pouring one for yourself...", sourceObjectiveStatus = "unverified-source-field" }
quests[26679] = { id = 26679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Revilgaz", description = "Something is happening outside.  Could the Bloodsail already be here?\n\nYou'd better get Revilgaz his doublerum.  Quickly.", sourceObjective = "Bring the Doublerum to Baron Revilgaz at Booty Bay.", progress = "Guess who showed up while you were gone?", completion = "<The Baron quickly empties his cup.>\n\nAH!  Much better, {name}.  Now, let's get down to business.  I believe that you and I have a town to save.", sourceObjectiveStatus = "unverified-source-field" }
quests[26680] = { id = 26680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, {name}, retrieve this crate for me for I miss it sorely.", sourceObjective = "Return Abercrombie's Crate to Abercrombie.", progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, {name}!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!", sourceObjectiveStatus = "unverified-source-field" }
quests[26681] = { id = 26681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", sourceObjective = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", progress = "A letter? What's this all about?", completion = "<Ello looks at the letter, and immediately pales.>\n\nYou fool! You've doomed us all!", sourceObjectiveStatus = "unverified-source-field" }
quests[26682] = { id = 26682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shambling Threat", description = "Dustwallow is Horde territory, {name}. The humans may have their little island and their precious sand bar, but the marsh belongs to us.\n\nIn time, we will surely win this stalemate with the humans. For now, we must master our own territory. The withervine bog beasts to the north rise from the marsh itself to attack any living thing that approaches. If we own this marsh, we must not let our own land fight back against us!\n\nSlay the bog beasts, if you wish to serve the Horde. You will be rewarded.", sourceObjective = "Slay 7 Withervine Creepers or Withervine Ragers in the marsh north of Brackenwall Village.", completion = "Well done, {name}. We'll be able to focus on greater threats here now.", sourceObjectiveStatus = "unverified-source-field" }
quests[26683] = { id = 26683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look To The Stars", description = "My gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars. According to Cog's blueprint, what I need first is a way to reflect light.\n\nI remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", sourceObjective = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", completion = "Why yes, I used to own a looking glass.", sourceObjectiveStatus = "unverified-source-field" }
quests[26684] = { id = 26684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Insane Ghoul", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an insane ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", sourceObjective = "Retrieve Mary's Looking Glass from the Insane Ghoul.", progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[26685] = { id = 26685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classy Glass", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", sourceObjective = "Kill Zzarc'Vul in the southern ogre mound in Duskwood and collect the Ogre Monocle.", progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, {name}.  Now I can continue my research. . .", sourceObjectiveStatus = "unverified-source-field" }
quests[26686] = { id = 26686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones That Walk", description = "There's even fouler undead left to deal with, {name}.\n\nTranquil Gardens Cemetery, further south of town, is a place you don't want to be caught in at night. The bones that rise from the ground there are cunning enough to remember how to swing an axe or cast a spell.\n\nI shouldn't need to explain how dangerous that makes them. Proceed with caution, but remember the people of Darkshire that will suffer if you falter.", sourceObjective = "Commander Althea Ebonlocke of Darkshire wants you to kill 5 Skeletal Warriors and 5 Skeletal Mages.", completion = "The people of Darkshire thank you, {name}.  You have proven yourself to be a great ally of The Night Watch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26687] = { id = 26687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements From Theramore", description = "Hawthorne dead... my own son murdered... the situation in the Barrens is out of control, {name}.\n\nI'm going to take charge of Fort Triumph and try to lock things down. To do that, I'm going to need reinforcements. Reinforcements that were promised from Theramore weeks ago!\n\nTravel to Theramore in Dustwallow Marsh and give Captain Garran Vimes an earful. What good is that blasted road through the swamp if the men and materiel aren't rolling in?", sourceObjective = "Travel to Theramore Isle in Dustwallow Marsh and talk to Captain Garran Vimes in the main barracks.", completion = "What now, soldier?\n\nReinforcements? For the Barrens? We've been bleeding supplies and men there for months!\n\nDoes someone need to remind Twinbraid of the attack on Northwatch? Our losses at Honor's Stand? What happened to the men I sent to Fort Triumph? We've nothing to spare!\n\nListen {name}, if you want to help out our cause, you'll focus your efforts here in Dustwallow. Between the deserters and the Horde encroachment... we could use a hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26688] = { id = 26688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane worgen in Brightwood Grove. We'll see if you have what it takes to hunt these monsters.", sourceObjective = "Kill 7 Nightbane Worgen in Brightwood Grove.", completion = "Impressive, {name}. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[26689] = { id = 26689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rotting Orchard", description = "The worgen infestation stretches further than Brightwood Grove. To the south, on the very edges of Darkshire itself, the Rotting Orchard is host to even more of the savage beasts.\n\nThe worgen there are more cunning, {name}, but just as savage and evil. They conjure foul shadows to tear their enemies apart from a distance. Go to the Rotting Orchard, and slay the Shadow Weavers to keep the town safe!", sourceObjective = "Kill 10 Nightbane Shadow Weavers at the Rotting Orchard.", completion = "You performed well against the Shadow Weavers, {name}. But even now, years after their first arrival, there seem to be so many to replace the ones we kill.\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[26690] = { id = 26690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile and Tainted", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", sourceObjective = "Kill 8 Nightbane Vile Fangs and 8 Nightbane Tainted Ones in Roland's Doom.", completion = "{name}, to be honest with you, I did not believe that you would get this far, but you are clearly a {class} to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation.", sourceObjectiveStatus = "unverified-source-field" }
quests[26691] = { id = 26691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Here you go, {name}. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", sourceObjective = "Bring Calor's note to Jonathan Carevin.", progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, {name}, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, {name}, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[26692] = { id = 26692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowhide Extinction", description = "Now that every Blackrock orc south of Lake Everstill is nothing more than ash and cinder, we can turn our attention to the Shadowhide gnoll army of Galardell Valley, directly north of here.\n\nI want you to head out there and kill 'em all, {name}! Initiate Operation: Extinction, soldier. For Bravo Company and for the Alliance!", sourceObjective = "Kill any 20 Shadowhide Gnolls.", completion = "<Danforth's voice comes in over the Bravo Company field kit.>\n\nHello? Is this thing on?\n\n<You hear Keeshan's voice in the background, and some muffled scrapes as they adjust the signal.>\n\nThere we go. Good work, {name}. We're closing in on the Blackrock high command. There's nowhere left for those dogs to run.", sourceObjectiveStatus = "unverified-source-field" }
quests[26693] = { id = 26693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Tower", description = "We got lucky with some vital intelligence from the locals of this valley. Those two behind us, the Ranthals, have informed me that the gnolls in Galardell Valley are being controlled by a powerful magus in the tower of Ilgalar. The problem is that the tower is sealed by a magical force field.\n\nThe first thing we need to do is get the key that will get you inside. The gnoll general, Fangore, has your ticket inside. Kill General Fangore and get the key.\n\nI'll be in touch.", sourceObjective = "Recover the Key of Ilgalar.", progress = "I hear you loud and clear, {name}.", completion = "<Keeshan comes in over the Bravo Company field kit.>\n\nNow that the easy part is over, it's time for phase two.", sourceObjectiveStatus = "unverified-source-field" }
quests[26694] = { id = 26694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Magus Doane", description = "<The Bravo Company field kit vibrates.>\n\nGood work, kid. I've got some vital intel for you. The magus in the tower is a human named Doane. Damned traitor is working for the Blackrock orcs. I want him dead.\n\nUse the key of Ilgalar and get inside that tower. Work your way to the top and show Doane what Bravo Company does with traitors.\n\nRendezvous back at Shalewind Canyon when the deed is done.\n\nKeeshan, over and out.", sourceObjective = "Kill Grand Magus Doane.", completion = "He teleported away? Mentioned Darkblaze? What the hell is going on here.\n\nLooks like it's time to strap in and finish this nonsense.", sourceObjectiveStatus = "unverified-source-field" }
quests[26695] = { id = 26695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Takeoff", description = "I've got an idea, but it's going to involve some footwork on your part.  As a goblin cartel, the Blackwater Raiders have a lot of explosives on hand.  In fact, I know for a fact that our old friend Narkk keeps a case in the back of his shop, in the Old Port Authority.\n\nGo grab them and bring them here, if they haven't already exploded.", sourceObjective = "Obtain Narkk's Handbombs from the Old Port Authority inside Booty Bay.", progress = "You're still alive?", completion = "You brought them!  I'm beginning to think the tide is turning in our favor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26696] = { id = 26696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Kalimdor", description = "Say, you haven't seen a fish about this long?  Short fins?  Responds to the name Steve?  He's blue?\n\nNever mind, I'll keep looking.\n\nActually... there was another reason I came here to Booty Bay.  Boss Krog, over in Dustwallow, is looking for new blood.  Someone to help us Stonemaul from getting overrun.  You look strong enough.\n\nWait on the edge of the pier for the next ship, then ride to Ratchet.  Gazlowe should be able to help you from there.\n\nSteve?  Steve!", sourceObjective = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe.", completion = "Yeah?  What can I do for ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[26697] = { id = 26697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Voyage of the Brashtide", description = "We'll never survive this attack with all these worgen pirates pouring into the harbor from the north.  Luckily, it looks like they're not armed with cannons, so if we can get you out of the harbor, you can attack from the skies.\n\nKebok, the Horde flight master's assistant, is right around the corner.  Talk to him and let him know that you're going to need his bravest wind rider.\n\nBring a couple armloads of handbombs with you.  You'll need all of them to stop those attack boats!", sourceObjective = "Speak with Kebok in Booty Bay to board a Bold Wind Rider. Then use the handbombs to destroy kill 85 Brashtide Crewmen and destroy 6 Brashtide Attack Boats.", progress = "We're still overwhelmed, matey.  Get back out there and protect my town!", completion = "I hope those mongrels know how to doggy paddle!\n\nActually, I take that back.", sourceObjectiveStatus = "unverified-source-field" }
quests[26698] = { id = 26698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Seahorn", description = "When the Brashtide pulled in, Seahorn grabbed the nearest weapon he could find and jumped off the ledge here.  You'll find him down below, probably pounding new holes into those worgen's skulls.\n\nHelp him out down there.  I can handle the motivation from up here.", sourceObjective = "Report to Fleet Master Seahorn in Booty Bay.", completion = "I should have known these Brashtide were alive and up to no good.  I'd written them off years ago.", sourceObjectiveStatus = "unverified-source-field" }
quests[26699] = { id = 26699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Brashtide", description = "The Brashtide are everywhere!  The Baron's Booty Bay Bruisers are no match for their sheer numbers, I'm afraid.\n\nWhile you're down here in the fray, why don't you help me get rid of a few of them?\n\nWhen you're done, don't bother coming back here.  I'll probably be pretty busy.", sourceObjective = "Kill 10 Brashtide Raiders in Booty Bay.", completion = "We need to keep moving, {name}.  Booty Bay won't hold out for much longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[26700] = { id = 26700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damsel's (Bad) Luck", description = "I heard that this ship here is the Damsel's Luck.  Didn't you used to be the captain of that thing?  You must know your way around it, then.\n\nThe Brashtide are our main concern, but we still don't want to take an unnecessary pummeling from those cannons of theirs.  Grab this rope behind me and take out some of those angry-looking corsairs.  Check in with the Baron when you're done.", sourceObjective = "Kill 8 Bloodsail Corsairs in Booty Bay.", progress = "You're really going to attack your former crew?", completion = "Attacking your former crewmen...\n\nYou really have grown into a real pirate, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26701] = { id = 26701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Brackenwall", description = "Listen, I got no special love for the Horde... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.\n\nThat two-headed ogre and his pet fish left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Krog.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", sourceObjective = "Speak with Bragok in Ratchet to fly to Brackenwall Village. Then report to Krog.", completion = "Lok'tar, {race}.  Welcome to Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[26702] = { id = 26702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Theramore", description = "Listen, I got no special love for the Alliance... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.  Sometimes better.\n\nJeyne left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Calia Hastings.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", sourceObjective = "Speak with Bragok in Ratchet to fly to Theramore. Then report to Calia Hastings.", completion = "Welcome to Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[26703] = { id = 26703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodsail's End", description = "We've nearly won the day, largely thanks to you.  One task remains, however... kill Fleet Master Firallon.\n\nIt looks like most of Firallon's crew is already dead, but I know that old sea dog well enough to know that he's not done yet.  No, he's cooped up tight in his cabin, ready to go down with his ship.\n\nSpeak with Kebok again to get a wind rider.  I'll try to hold off the cannonfire while you're on board.", sourceObjective = "Speak with Kebok in Booty Bay to get a wind rider, then kill Fleet Master Firallon.", progress = "Firallon is still at large, {name}.  The Bloodsail don't leave until he dies.", completion = "{name}!  You're awake!  We found you bobbing in the harbor, shortly after the remaining attackers had turned tail.  We were worried about you for a while there...\n\nI've been meaning to thank you, {name}.  Not only did you provide us with the intelligence to prepare for this attack, but you helped fight off the Bloodsail AND the Brashtide.  Your name will always be remembered here in Booty Bay.\n\nWe here in Booty Bay pride ourselves on our booty.  Care to take first pick?", sourceObjectiveStatus = "unverified-source-field" }
quests[26704] = { id = 26704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26706] = { id = 26706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endgame", description = "We need to get rid of that flying gunship if our people have any chance of escaping.\n\nHere's the plan.  Keel Harbor had its share of rebel sympathizers in the old days.  I've managed to round up a hefty amount of incendiary explosives from one of our storehouses.\n\nWe're going to hit the enemy with a force small enough to fly undetected.  The night elf hippogryphs should do the trick.\n\nTobias will give you the signal when we're ready to go.", sourceObjective = "Jump on a Hippogryph when Tobias signals you and destroy the Horde Gunship.", progress = "The only risks worth taking are the ones that lead to victories worth having.", completion = "We did it, {name}.  We've started the evacuation.  If we leave soon we'll leave the Forsaken fleet in the dust.", sourceObjectiveStatus = "unverified-source-field" }
quests[26707] = { id = 26707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deadly Vine", description = "I need large amounts of corpseweed for Master Harris's concoctions. It's difficult to obtain, but we can't let our supply dwindle.\n\ncorpseweed is tough stuff to tangle with... the plant will get you before you get it, if you're not careful! But if you'd like to help out, I'll eagerly pay you for any you gather yourself.\n\nYou'll find plenty of it all over the Yorgen Stead to the southeast.", sourceObjective = "Collect 5 pieces of Corpseweed.", progress = "Do you have the corpseweed?", completion = "I thank you, {class}... and I'm sure the worgen that may be returned to sanity with the potion this will make would thank you too.", sourceObjectiveStatus = "unverified-source-field" }
quests[26708] = { id = 26708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", description = "I'm here to help you and Bravo Company end this mess. You're to get in the Bravo Company siege tank and clear a path to Keeshan's Post on the other side of the valley, north of here.\n\nThis is a high alert situation soldier as the Blackrock orcs are now aware of your location and sending a large force to meet you head on. Terminate them all with extreme prejudice.\n\nI'll see you on the other side. May the Light have mercy on your soul.", sourceObjective = "Use the Bravo Company Siege Tank to kill 200 Blackrock soldiers.", progress = "We're ready for the final assault.", completion = "The only thing left to deal with now are the orcs holding out at Stonewatch Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[26709] = { id = 26709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Throne", description = "I am returning to my throne. I've no desire to see any more of these Earthen Ring, but you remain welcome here, {race}. If you wish to help us rebuild our realm, perhaps we can help you in return.\n\nAll things in time.", sourceObjective = "Seek out Therazane at Therazane's Throne.", completion = "You returned. This is good. The Stone Lords have been asking after you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26710] = { id = 26710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost In The Deeps", description = "Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths.\n\nHe's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it.\n\nHe seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.", sourceObjective = "Find Pebble within the Crumbling Depths and lead him safely out of the tunnels.", progress = "Pebble is much smarter than he lets on, but he is spoiled. I fear one day he may suffer for it.", completion = "You've done well. Now that these rocklings are free to learn our ways, they will grow tall and strong.\n\nOne day, we will extinguish the gyreworm infestation from our realm, and these rocklings shall no longer be plagued in their youth.", sourceObjectiveStatus = "unverified-source-field" }
quests[26711] = { id = 26711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to the Bank", description = "Yo, baby. Wassup? You ready for the party?\n\nNo?! You know I love you, so I don't know how to say this, but check it... I think you need to swing into town to buy a new outfit for the party.\n\nDon't look at me like that... you want to look gooood, right? Don't you want to look super fine for me? I am your boyfriend after all!\n\nSwing by the bank first and pull out plenty of macaroons. You don't want to buy any of that cheap stuff!", sourceObjective = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan.", completion = "Oh, it's you, ma'am! Sorry, I didn't recognize you at first with all of these commoners milling about.\n\nYou people cool your heels! {name} is here!\n\nHere are your macaroons, ma'am. Come back anytime if you need more.", sourceObjectiveStatus = "unverified-source-field" }
quests[26712] = { id = 26712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to the Bank", description = "Hi, babe. Are you ready for the party?\n\nNo?! You know I love you, right? I think you need to swing into town and buy a new outfit for the party.\n\nDon't look at me like that... you want to look your best? Don't you want to look good for me? I am your girlfriend after all!\n\nMake sure you swing by the bank first and pull out plenty of macaroons. Don't buy any of that cheap stuff!", sourceObjective = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan.", completion = "Oh, it's you, sir! Sorry, I didn't recognize you at first with all of these commoners milling about.\n\nYou people cool your heels! {name} is here!\n\nHere are your macaroons, sir. Come back anytime if you need more.", sourceObjectiveStatus = "unverified-source-field" }
quests[26713] = { id = 26713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown at Stonewatch", description = "Only the Blackrock high command remains, {name}. They're all holed up in Stonewatch Keep, directly south of our position here at Keeshan's Post. I want you and the rest of Bravo Company to enter Stonewatch and put an end to the Blackrock orc invasion.\n\n{name}, no survivors.", sourceObjective = "Kill Tharil'zun and Gath'Ilzogg.", completion = "<The Bravo Company field kit beeps loudly.>\n\nCome in, {name}. Are you there? If you can hear me: Blackrock has the upper hand. I repeat. Blackrock has the upper hand. GET BRAVO COMPANY OUT OF TH...", sourceObjectiveStatus = "unverified-source-field" }
quests[26714] = { id = 26714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkblaze, Brood of the Worldbreaker", description = "As Troteman cuts out, the world around you grows eerily silent. In the distance you see a full grown black dragon!", sourceObjective = "Use the Horn of Summoning to call for Darkblaze. Defeat Darkblaze.", progress = "...", completion = "<A single tear rolls down Troteman's left cheek.>\n\nThey died in defense of the Alliance. In defense of our kingdom! Heroes, all of them, and they will be laid to rest as such.", sourceObjectiveStatus = "unverified-source-field" }
quests[26715] = { id = 26715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion Stormrage", description = "I've spoken to Malfurion of your coming. He seemed very interested in meeting you himself.\n\nYou should go to him in the Temple of the Moon. You'll find him standing beside our beloved Tyrande Whisperwind, where he's remained diligently ever since his return.\n\nI must warn you... Malfurion has his reservations. You may be carrying a great burden for your people by being the one to meet with him.", sourceObjective = "Speak to Malfurion Stormrage in the Temple of the Moon in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26717] = { id = 26717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Yorgen Worgen", description = "My kinsmen at Raven Hill are concerned with curing the feral worgen in these forests. The condition itself cannot be lifted, but sanity can be restored to those not too far gone.\n\nWhile most here have proven beyond help, we keep an eye out for those that retain vestiges of their minds... attachments to their old lives.\n\nI've seen a lone worgen lurking the Yorgen Farmstead, digging in a pile of dirt between the buildings...could you check out that pile and see if he's left anything?", sourceObjective = "Examine the Mound of Loose Dirt at the Yorgen Farmstead.", completion = "Sounds like a close call! But he ran off without harming you further...\n\nHe might be still fighting it. Master Harris must know!", sourceObjectiveStatus = "unverified-source-field" }
quests[26718] = { id = 26718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb to Badlands", description = "Something bad happened." }
quests[26719] = { id = 26719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Master Harris", description = "Master Harris will want to know of this immediately.\n\nHere, take this package of corpseweed down the road to the camp at Raven Hill. Tell him what we saw at the Yorgen Stead.", sourceObjective = "Deliver the Bundle of Corpseweed to Oliver Harris at Raven Hill.", progress = "What brings you out this way, my good sir?", completion = "Welcome to our humble camp. I wouldn't call it pleasant, but it's at least somewhat private.\n\nBeg your pardon? A worgen at the farm?", sourceObjectiveStatus = "unverified-source-field" }
quests[26720] = { id = 26720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curse We Cannot Lift", description = "What we do here is not a cure. The transformation cannot be removed once inflicted. But the mind...\n\nThe mind can be restored, through alchemy,  if enough is left intact. This worgen you've encountered sounds like he's fighting to stay aware, {name}. We've got to find him again.\n\nIf he's fled the Yorgen Stead, search the Addle Stead to the south; he may be lurking in one of the buildings.\n\nInject him with this ampule to tranquilize him. You'll need to be quite close.", sourceObjective = "Search the Addle Stead for the Lurking Worgen and use Harris's Ampule to tranquilize it.", completion = "You've got him!\n\nNo time to lose, then. We'll prepare to administer the serum right away.\n\nJITTERS! Get ready!", sourceObjectiveStatus = "unverified-source-field" }
quests[26721] = { id = 26721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jitters-Bugs", description = "M-Master Harris requires many reagents for his serums. He has me gather them for him.\n\nMost of it's not so bad... I mean, the corpseweed is pretty bad, but it's not as bad as the widow venom. Have you seen the widows around here? The hatchlings are the size of a man. Even with a gun, I can't stand to go out hunting them!\n\nIt's just too terrifying. If you'll go do it for me, I'll gladly pay you! Just bring me back some widow venom! You'll find them all in the woods to the east, just north of the road.", sourceObjective = "Collect 8 Widow Venom Sacs from Black Widows.", progress = "Did you get it? Please tell me you got it...", completion = "Oh thank you, thank you! You've saved me from having to go out in the woods with those awful things!\n\nAt least for a day, that is...", sourceObjectiveStatus = "unverified-source-field" }
quests[26722] = { id = 26722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Below", description = "<You attach the arch to the rod, and the artifact is nearly complete. A large gap still sits at the center of the holy symbol's head.>\n\n<Once again you feel it tug your arm, urging you towards the hole in the wall and the winding tunnel ahead. The last piece must be through there.>", sourceObjective = "Search the tunnel under the Dawning Woods Catacombs for the Lightforged Crest.", completion = "<In the darkest depths of this earthen tunnel, you spy the faintest gleam. The last piece is found!>", sourceObjectiveStatus = "unverified-source-field" }
quests[26723] = { id = 26723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Morbent Fel", description = "Before I was lost to the woods, the last thing I remember is Morbent Fel. He was a vile necromancer, and the reason this land swarms with so many vile undead.\n\nI asked an adventurer to help me put an end to him. I thought they did! But Sister Elsington tells me the land still crawls with ghouls and spectres ripped from the grave.\n\nMorbent Fel should have breathed his last in the house on Forlorn Rowe, north of Raven Hill Cemetary. Go there and see what's become of him...", sourceObjective = "Search Forlorn Rowe for signs of Morbent Fel.", completion = "His clothes and bloodstains? If it's not tricks, it's something worse...", sourceObjectiveStatus = "unverified-source-field" }
quests[26724] = { id = 26724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lurking Lich", description = "The others here share my suspicion. Morbent Fel lives on in undeath...and may be even more powerful than before. A necromancer was struck down, but a lich may have risen in his place. And now he continues to ruin this land.\n\nI remember Duskwood before all this, {name}. I remember bright skies and peaceful woods. This can't stand! Morbent Fel must be stopped for good.\n\nSpeak to Sister Elsington. Her vision might guide you to where Morbent Fel is, and how he can be defeated.", sourceObjective = "Speak with Sister Elsington.", completion = "It's heartening to see one so recently recovered be so concerned with the plight of others. Sven spares himself suffering by not dwelling on his own misfortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[26725] = { id = 26725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guided by the Light", description = "Sven is correct. I can feel the presence of a powerful evil deep beneath the Raven Hill Cemetery. Evil lurks in its catacombs, and Morbent Fel must be the source.\n\nYou will need the power of the Light to strike him down, {name}. Sven told me the heroes who first slew Morbent Fel wielded an artifact of lightforged iron, imbued with holy power. That artifact is still here!\n\nI can feel it as well, a glimmer of light amidst the darkness. Search Raven Hill for it, and let the Light guide you through it.", sourceObjective = "Find the Lightforged Rod in Raven Hill Cemetery.", completion = "<Buried in the cold dirt, you find a brilliant metal shaft. But there are holes where pieces of the artifact are clearly missing.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26726] = { id = 26726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triumphant Return", description = "Return to Lakeshire and let Solomon know that the Blackrock invasion has been stopped. Make sure he understands the cost at which our freedom came - that we lost five of our finest heroes to save Redridge and ultimately, Stormwind.\n\nYou are the last surviving member of Bravo Company, {name}. It is up to you to keep its legacy alive.\n\nDismissed.", sourceObjective = "Report to Magistrate Solomon at Lakeshire in Redridge.", completion = "They will never be forgotten, {name}. What you and the rest of Bravo Company sacrificed in order to save Redridge will be a tale told for ages to come.\n\nWhile I can in no way make up for the loss of your friends, I feel that you must be rewarded for such a heroic deed. These are Keeshan's possessions - the only things we found when we dredged the lake for his body. Troteman has informed me that Keeshan would have wanted you to take something as the lone surviving member of Bravo Company. Remember them, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26727] = { id = 26727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Embalmer's Revenge", description = "You're not the first fool to be manipulated by Abercrombie! That doddering old man is known as The Embalmer to us. He's a vile necromancer and a blight upon this town.\n\nAnd now, sewn together and given life by the very materials you brought him, his horrible creation approaches!\n\nThat hideous creature will be upon us in mere moments! If you have any heart, {name}, you'll help the Night Watch drive off the abomination and save our town!", sourceObjective = "Slay Stitches in Darkshire.", progress = "Don't just stand there! He's right outside! By the light, man, do something!", completion = "Thank the Light, he's gone...\n\nI'll say you've made amends by helping save the lives of those here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26728] = { id = 26728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Duskwood!", description = "{name}, the citizens of Duskwood are in dire need of your assistance! I have here a letter from Commander Althea Ebonlocke, leader of the Night Watch, pleading for help.\n\nTo reach Darkshire you should travel across the bridge located in the southwest corner of Redridge. Once you cross the bridge you will be in Duskwood. Then you just follow the road to Darkshire. Beware of the savage beasts that stalk the countryside!", sourceObjective = "Report to Commander Althea Ebonlocke at Darkshire in Duskwood.", completion = "You are the help that we requested?\n\n<Althea sighs.>\n\nI suppose you will have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26729] = { id = 26729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Elementals", description = "I arrived in Stranglethorn to study a feature known as the Altar of Naias, but made the unfortunate choice of denying Colonel Kurzen's advances, which earned me several years in that cage.  Now that I'm out, I figure I might as well continue with my original studies.\n\nThe altar is on an island to the west, south of Zul'Kunda.  Gather some of the bracers from the island's water elementals.\n\nOh, and you can use this device when you're finished.  No need to make you walk all the way back here.", sourceObjective = "Acquire 6 Water Elemental Bracers.", progress = "Yes, {name}?", completion = "These will do for my purposes.  Though we can't activate the altar with bracers alone...", sourceObjectiveStatus = "unverified-source-field" }
quests[26730] = { id = 26730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can Take the Murloc Out of the Ocean...", description = "I need something to cut into the raw, elemental power of these bracers... something strong and abrasive, but still of the sea.\n\nThe Murkgill murlocs have moved inland from the sea, but they still carry vials of sea salt on them.  What they use it for, I can't be sure, but it will serve for our studies.  You can find the Murkgill in the glade south of the Rebel Camp and east of Bal'lal ruins.", sourceObjective = "Obtain 6 vials of Sea Salt from Murkgill murlocs in Northern Stranglethorn.", progress = "The salt?", completion = "We have what we need.  Are you ready to activate the Altar of Naias, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26731] = { id = 26731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar of Naias", description = "The salt you brought was sufficient to activate the bracers' innate enchantments.  I have taken these enchantments and combined them into a summoning token... a gift, if you will.\n\nReturn to the Isle of Naias, and place the gift on Naias' altar.  Call me again once you have Naias' heart.", sourceObjective = "Use the Gift of Naias to summon Naias, then obtain the Heart of Naias.", progress = "I eagerly await the results.", completion = "My colleagues within the Kirin Tor will be happy to learn that the heart is ours.\n\nThank you for your assistance, {name}.  I couldn't have done it without you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26732] = { id = 26732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Medicine", description = "I have a feeling that Kurzen's Medicine Men are distributing more than just medicine.  Kurzen needs some way to quelch insubordination, and an elixir under the guise of \"medicine\" would be the perfect way to do that.\n\nWe need those remedies for research.  Search the Kurzen Compound to the southeast - his medicine men and jungle fighters should carry the remedies on their bodies.", sourceObjective = "Obtain 7 Jungle Remedies from the Kurzen Compound.", progress = "I'm a little bit of an alchemist in my spare time, you know.", completion = "Well done, {name}.  Now, let's see what they've got in this elixir of theirs...", sourceObjectiveStatus = "unverified-source-field" }
quests[26733] = { id = 26733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control Sample", description = "<Brother Nimetz analyzes the samples you've given him.>\n\nThis... this is just basilisk blood!\n\nNo, it's mostly basilisk blood.  They've added something to it though.  I'll need a control sample to perform a proper comparison.\n\nThey most likely obtained the blood from the crystal spine basilisks, found to the east of their compound.  Bring me back some pure samples, and I'll have this elixir figured out.", sourceObjective = "Obtain 7 samples of Crystal Spine Basilisk Blood.", progress = "There's something not quite healthy about this elixir, {name}.  Even though I haven't completed my analysis, I can sense it.", completion = "This will do.  Please hold on for a moment while I test this out.", sourceObjectiveStatus = "unverified-source-field" }
quests[26734] = { id = 26734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of the Madness", description = "After reducing the basilisk blood out of the elixir, I've uncovered an unusual precipitate.  It appears to be a blue crystal of some sort...\n\n<Brother Nimetz consults his notes.>\n\nIt's not a singing blue crystal... not a pulsing blue shard...\n\n<He flips forward a few pages.>\n\n... not a piece of the Mind's Eye.  Nope, this isn't something we've seen before in Stranglethorn.  If anyone has any more of this substance, I want it.  Check the high-ranking Kurzen troops, in the back of their cave.", sourceObjective = "Obtain a Whispering Blue Stone from Kurzen troops within the Stockpile.", progress = "Make sure you handle that stuff carefully, {name}.  We don't know what it is.", completion = "<Brother Nimetz opens up a pouch and lets you place the crystal inside.>\n\nI knew they'd have some more of this substance.  I'm going to send this to my contacts at Fort Livingston, to the south.  Hopefully they'll have some more luck with it.\n\nThank you for everything, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26735] = { id = 26735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Kurzen", description = "Hello, {class}.\n\nWe are soldiers of Stormwind, and rebels from Kurzen's Compound, a large outpost that you'll find just to the southeast of here.  We were under the command of Colonel Kurzen, until he and those close to him started to descend into madness...\n\nWe rebelled, set up camp here, and stood against Kurzen.  Now, my sources are telling me Kurzen has disappeared.  I trust my source, but it would help to hear from a third party.  Please, head into the compound and find some documentation of his fate.", sourceObjective = "Obtain the Kurzen Compound Prison Records and the Kurzen Compound Officers' Dossier.", progress = "What were you able to find, {name}?", completion = "They KILLED him?  And all this time, I thought he had them underneath an iron bootheel...", sourceObjectiveStatus = "unverified-source-field" }
quests[26736] = { id = 26736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spared from Madness", description = "Kurzen's death is a relief, but what's more interesting, and perhaps more immediate, is the sign of some potential allies within the compound.\n\nI don't care what it says on that prison record, I know EXACTLY why those 3 were locked up: refusal to follow orders.  They must have been spared from the madness, much like my fellow rebels here, and incarcerated for speaking up.\n\nFind them, {name}.  Find them, and send them back here.", sourceObjective = "Rescue Berrin Burnquill, Emerine Junis, and Osborn Obnoticus inside Kurzen's Compound.", progress = "Bring those three back here to my camp, {race}... alive or dead.", completion = "Thank you, {name}.  It looks like my suspicions were correct... the three prisoners seem to have escaped the affliction that gripped Kurzen and the rest of his men.\n\nBefore you arrived, Emerine teleported them over to Stormwind to get cleaned up after their ordeal.  They promised to return soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26737] = { id = 26737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping Kurzen's Legacy", description = "Now that our allies have been evacuated, it's time to run a final raid on Kurzen's Compound.  They will never be weaker than they are right now, and with your help, we may be able to weaken them beyond repair.\n\nThose four names that were listed in the Officers' Dossier - Anders, Gaulus, Miranda, and Esquivel - will be the highest-ranking personnel remaining.  Look for them in that cave in the back of their compound.  Removing all four will be devastating to Kurzen's forces.\n\nGo with honor, {name}.", sourceObjective = "Kill Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel within The Stockpile.", completion = "Marvelously executed, {name}.  My men and I can handle the rest.\n\nWith Kurzen out of the picture, we may be able to continue our original expedition here in Stranglethorn, which was... ahh...\n\nNo matter.  Please, feel free to peruse our armor stores.  You may find something that fits you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26738] = { id = 26738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Hatched", description = "While looking through this soldier's possessions, you look down to see a newborn raptor hatchling looking back up at you.  Was it following this Kurzen militiaman the whole time?\n\nYou can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nPerhaps someone back at the Rebel Camp will know what to do with a raptor hatchling.", sourceObjective = "Bring the Lashtail Hatchling to Corporal Sethman at the Rebel Camp in Northern Stranglethorn.\n\nProvided item:", completion = "Yes, the little one seems to have taken a liking to you.  You're lucky... at this age, the raptors are calm, peaceful, and easily trained.  Keep her, {name}... she may come in handy.\n\nIn fact...", sourceObjectiveStatus = "unverified-source-field" }
quests[26739] = { id = 26739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the basilisks of Stranglethorn, which can be found to the east, beyond Kurzen's Compound.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed basilisk meat.", sourceObjective = "Kill Crystal Spine Basilisks in Northern Stranglethorn, and let your Lashtail Raptor eat 40 bites of their meat.", completion = "She looks bigger already!  You can see, these raptors grow quickly.  You are lucky to have found such a strong companion.\n\nKeep her by your side as long as you can, {name}.  I'm sure she will prove to be an asset in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[26740] = { id = 26740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  It used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.  Last I heard, he was staying with Nesingwary in the hunters' camp just to the south.", sourceObjective = "Bring Krazek's Crock Pot to Krazek.", progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price...", sourceObjectiveStatus = "unverified-source-field" }
quests[26741] = { id = 26741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26742] = { id = 26742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodscalp Insight", description = "I never got to properly thank you for saving me.\n\nThank you, {name}.\n\nI'm still a little fatigued from my captivity, so I thought you might help me with my studies.  As a shaman of the Wildhammer clan, I'm very interested in the shamanic practices of the Bloodscalp tribe.\n\nTheir magic seems to have diverged in an interesting direction.  If I had one of the totems that their shaman use, I could begin my studies.  You'll find them at the Bal'lal ruins, on the coast to the southwest.", sourceObjective = "Obtain a Bloodscalp Totem from a Bloodscalp Shaman.", progress = "Beware: they may put up a fight.", completion = "<Berrin studies the inscriptions on the totem.>\n\nI think I can read this text... Fascinating!\n\nTsul'kalu, Mahamba, Pogeyan... what are these names?", sourceObjectiveStatus = "unverified-source-field" }
quests[26743] = { id = 26743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred to the Bloodscalp", description = "Ahh... these must be names of their totemic creatures - the animals that they attribute to the spirits.  Let's see... Mahamba as water, Tsul'Kalu as earth, Pogeyan as... air?  Fire?  I can't make this part out.\n\nI'd like some more information on these spirits of theirs.  The Bloodscalp have a camp close to here, in the Tkashi ruins.  Maybe you can find some details there.", sourceObjective = "Obtain an Icon of Tsul'kalu, an Icon of Mahamba, and an Icon of Pogeyan from Bloodscalp trolls in the Tkashi Ruins.", progress = "It's likely that these totemic creatures are based on some of the fantastic creatures that roam this jungle.", completion = "First you save me from the madman's jail cell, and now you bring me some keys to understanding trollish shamanism.\n\nThis is turning out to be a pretty good week!\n\nThank you again, {name}.  I will see to it that you have the support of the Wildhammer clan as you continue on your journeys.", sourceObjectiveStatus = "unverified-source-field" }
quests[26744] = { id = 26744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Roots", description = "On a somewhat unrelated note, I've been putting together a collection of troll stories and legends for a... personal project.  I was just thinking you might be able to help me find some of them.\n\nThe Bloodscalps at the Bal'lal ruins, on the coast to the southwest, maintain a large tablet documenting some of their stories.  Of course, I'll reimburse you if you're able to bring any of these stories back to me.", sourceObjective = "Obtain the Bloodscalp Lore Tablet from the Bal'lal Ruins in Northern Stranglethorn.", progress = "Did you make it down to Bal'lal Ruins yet?  Did you find the tablet?", completion = "To be honest, I'm sending this information home to Stormwind, for my wife and son.  They love to hear about what I've been doing out here in the jungle, and I only get to visit so often.  Every little bit helps.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26745] = { id = 26745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nOsborn Obnoticus, the gnome you saved from Kurzen's Compound, is an expert in troll history and physiology.  Maybe he'll have some idea what makes this one so special.", sourceObjective = "Report to Osborn Obnoticus at the Rebel Camp and show him your Lashtail Hatchling's new skull.\n\nProvided item:", completion = "What do we have here?  A young raptor, and her pet {race}.  Hah!\n\nMore importantly, what is that skull you have there?  This was no ordinary troll.  He was big...\n\n\n\n... and strong, too.  You know, I've been meaning to try my hand at some troll magic.  How hard could it be?  Let's use this strong fellow as a test subject, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[26746] = { id = 26746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nose for This Sort of Thing", description = "<Osborn looks at the skull again.>\n\nIn life, he was strong, powerful, a lord among trolls.  With our help, he can be a lord once more.\n\nThe Bloodscalp scavengers that wander the ruins to the southwest hoard magical fetishes that can help us.  They hide these artifacts under the ground.  Use your hatchling to find these artifacts, {name}... then bring them here.", sourceObjective = "Use your Lashtail Hatchling to sniff out 8 Tkashi Fetishes.", progress = "How many did you find?", completion = "These will provide a bit of... what's the troll word?  Voodoo?  Juju?  Tiklabang?\n\nIt doesn't matter.  If we're going to re-build a troll, we need troll magic, and these fetishes are full of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26747] = { id = 26747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Physical Specimen", description = "The soul is ready, but the body is not.  For a skull as well-formed, as marvelous, as beautiful as this... we will need a suitable body.\n\nThe chief of the Bloodscalps, Gan'zulah, won his throne with brute force.  If he still lives, you'll find him in Zul'Kunda, to the west.\n\nTaking his body won't be easy, but nothing a sturdy {class} like yourself couldn't handle.  Bring it back here when you're done.", sourceObjective = "Obtain Gan'zulah's Body from Zul'Kunda.", progress = "Gan'zulah was a brute and a tyrant.  I've got a feeling that this troll will be different.  This troll magic is easier than I thought it would be!", completion = "You have done well, {race}.  We have a head, a body, and some juju-voodoo-mojo nonsense.  Now, just a little shock of electricity to get things started, and...", sourceObjectiveStatus = "unverified-source-field" }
quests[26748] = { id = 26748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodlord Mandokir", description = "{race}.  You just resurrected your worst nightmare.  You didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me that raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the gnome will taste my rage.", sourceObjective = "Deliver the Lashtail Raptor Egg Fragment to Bloodlord Mandokir in the Rebel Camp.", progress = "All I ask is the raptor, {race}.  Give it to me, and the gnome lives.", completion = "I'm glad to see you've come to your senses.\n\nCome and visit us in Zul'Gurub sometime, {race}.  I'll be watching...", sourceObjectiveStatus = "unverified-source-field" }
quests[26749] = { id = 26749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess Thaalia", description = "Thank you, {name}.  I know you didn't have to save my life.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe explorers at Fort Livingston, far to the south, may know more.  Speak with their priestess.", sourceObjective = "Speak with Priestess Thaalia at Fort Livingston in Northern Stranglethorn.", completion = "Mandokir is alive, yes.\n\nYou are responsible, yes.\n\nYou may be able to stop him still, yes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26750] = { id = 26750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the Stonemother's Call", description = "It is time. The Stonemother will speak with you. You can find her throne in northern Deepholm, above the Scoured Reach.", sourceObjective = "Speak to Therazane, the Stonemother.", completion = "So you've come.\n\nFleshlings just like you killed my daughter... my only daughter. With no provocation.\n\nNot sated at stripping me of my family, more of you flocked to Deathwing to serve him in ravaging my home.\n\nYou're quite arrogant to come before me asking for MY help. I'm tempted to crush you where you stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26751] = { id = 26751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", sourceObjective = "Slay 7 Bloodscalp Mystics, 7 Bloodscalp Hunters, 7 Bloodscalp Scouts, and 1 Bloodscalp Beastmaster.", progress = "We appreciate what you're doing for us here in Stranglethorn, {name}.", completion = "Balance is restored - for now.  We may call on you again in the future, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26752] = { id = 26752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Stonemother", description = "Stay where you are, champion. I have not yet decided what to do with you or your Earthen Ring.", sourceObjective = "Attend the Audience with the Stonemother.", completion = "Ya've done well, brotha. Da Stonemother be listenin' and da World Pillar is not far from our reach.", sourceObjectiveStatus = "unverified-source-field" }
quests[26753] = { id = 26753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls of the Dead", description = "<In front of you, the bare earth slopes down towards the dark entrance to the crypts.>\n\n<You can feel the tug of the lightforged artifact urging you towards it. Perhaps the other piece is down there?>", sourceObjective = "Find the Lightforged Arch within the Dawning Woods Catacombs.", completion = "<In the dirt of this alcove, your eye catches the shine of brilliant metal. You've found another piece of the artifact!>", sourceObjectiveStatus = "unverified-source-field" }
quests[26754] = { id = 26754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbent's Bane", description = "<The pieces fit, and the holy artifact is restored, gleaming with sacred light. This should let you defeat Morbent Fel's dark magic.>\n\n<Further down the tunnel, away from the direction you came from, a heinous cackle rings out. It's the clattering laugh of a lich. Morbent Fel is just ahead!>", sourceObjective = "Use Morbent's Bane to weaken Morbent Fel and defeat him.", completion = "May the disgusting monster stay dead this time!\n\nI'll head down there and scatter his remains to ash myself, {name}. You've done a great thing; perhaps in time Duskwood can return to its former peaceful state.", sourceObjectiveStatus = "unverified-source-field" }
quests[26755] = { id = 26755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them off the Front", description = "Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine.\n\nWell, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag.\n\nWe have to keep them off the front!", sourceObjective = "Bombard 30 Fungal Terrors and/or Stone Trogg Reinforcements.", progress = "Get back in a catapult and put those things back in the ground. The line's barely holding!", completion = "That's a great start, {name}, but we're going to need you to fly over into the town and stir up some trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[26760] = { id = 26760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry For The Moon", description = "I'm hopeful, but let's remain professional. It's business as usual for this one.\n\nInto the guillotine he goes... and if the alchemy doesn't take, he won't be getting back out of it.\n\nJitters and I will attend to this. Please, just stand back and watch from a safe distance.", sourceObjective = "Watch Oliver Harris and Jitters attempt to cure the Lurking Worgen.", completion = "Success... Finally! I can't thank you enough for giving me the chance to work the cure myself.\n\nOur new friend may be in need of some help as well. You might want to speak with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[26761] = { id = 26761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat to the Kingdom", description = "There is no doubt that the Defias pose a great threat to the kingdom, but we certainly cannot enter their hideout and hope that everything will work itself out. No, an assault against the Defias is going to take time and planning. I want you to leave the logistics to me. Our kingdom has other threats that must be dealt with immediately!\n\nTravel east through Elwynn to Redridge and report to Magistrate Solomon in Lakeshire. I will call for you when we are ready to attack the Defias.", sourceObjective = "Report to Magistrate Solomon at Lakeshire in Redridge.", completion = "I heard about the Defias making a return. Terrible news. I wish I had better news, but it would appear that Lakeshire is under attack! We are losing citizens left and right. Our own guards are spread far too thin to handle the situation. We need a hero to step up!", sourceObjectiveStatus = "unverified-source-field" }
quests[26762] = { id = 26762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reactivate the Constructs", description = "We sent a number of our war constructs north into Needlerock Slag, but none of them ever returned. We know that the stone trogg mystics have done something to them.\n\nWhat we're concerned about is that the mystics will control and turn them against us, like they have with the fungal giants.\n\n{name}, go into the stone trogg town and reactivate the constructs.", sourceObjective = "Reactivate 5 Deactivated War Constructs.", progress = "We'll need a few more reactivated. The last thing we want is to have to face our own constructs on top of all of this!", completion = "That was a nice bit of work, {name}.\n\nWith our constructs back up and running behind their main lines, it's only a matter of time now before we make the big push through and rescue the Stonefather.", sourceObjectiveStatus = "unverified-source-field" }
quests[26763] = { id = 26763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company Mining", description = "If I'm going to repair this pot, I'm going to need reagents.  And to get them, you're going to have to do an eensy little bit of killing.  I hope you don't mind.\n\nThose dastardly Venture Company geologists have been collecting some tumbled crystals that will suffice for what I need.  You'll find them around their Base Camp, on the other side of Lake Nazferiti, to the east.\n\nI don't care what you have to do to get them.", sourceObjective = "Obtain 5 Tumbled Crystals from Venture Co. forces near Lake Nazferiti.", progress = "Do you have those crystals?", completion = "These will work fine.  Just a moment please.\n\n<Krazek thrusts the stones into the cooking pot and wiggles them around a bit.>\n\nAll fixed!", sourceObjectiveStatus = "unverified-source-field" }
quests[26764] = { id = 26764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Low", description = "You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east.  Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors.  I'm sure they'll appreciate it.", sourceObjective = "Free 3 Enslaved Druids from the Venture Co. Base Camp.You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east. Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors. I'm sure they'll appreciate it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26765] = { id = 26765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Corporal Kaleb", description = "So, this pot is fixed.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", sourceObjective = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp in Northern Stranglethorn.", progress = "Hello, {name}.  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, {name}.\n\nI hope Krazek didn't give you too much trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[26766] = { id = 26766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Game, Big Bait", description = "We're only going to get one shot at capturing Abyssion, {name}.  Let's make it count.\n\nWe'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf.\n\nTo lure the stone matriarch, we're going to need to gather sufficient bait.\n\nTake this knife and carve 5 sides of basilisk meat.  That ought to be enough even for her appetite.", sourceObjective = "Use Mylra's Knife to obtain 5 Sides of Basilisk Meat from dead Jadecrest Basilisks.", progress = "Did you obtain the meat?", completion = "That should be enough to lure the beast, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26767] = { id = 26767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.", sourceObjective = "Make a breadcrumb quest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26768] = { id = 26768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch a Dragon", description = "Having a dragon guard the fragment was a smart move on the enemy's part.  They can keep moving its location any time we get close to it.\n\nCatching Abyssion will be extremely difficult, but I have a plan that might help.\n\nThe Twilight's Hammer uses magical traps to bind stone drakes to the ground while they drain their energy.\n\nIf we can get our hands on one of these, we might be able to ground the Twilight Dragon for just long enough.\n\nGo east of here, to the Alabaster Shelf, and obtain a trap.", sourceObjective = "Obtain a Dragon Snare from the Twilight Dragonstalkers.", progress = "If the snares are good enough for stone drakes, they might work on Abyssion.", completion = "Let's see if the snare can ground something larger than a drake.", sourceObjectiveStatus = "unverified-source-field" }
quests[26769] = { id = 26769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raging River Ride", description = "Enjoy your cut of the loot, {name}!\n\nI hate to share, but business is business. And that double-dealer Nozzlepot is guaranteed a 10% cut of this treasure. Can you deliver this to him at his outpost in the north?\n\nHe's got a little research station upstream, along the river. If you travel just northeast of town here, Horton Hornblower can give you a free ride on one of his riverboats. Tell him I sent ya!", sourceObjective = "Board Horton Hornblower's Riverboat northeast of Ratchet and get a riverboat ride to Nozzlepot's Outpost.", progress = "Welcome, {class}. Fresh off the boat from Ratchet? Any news?", completion = "<Nozzlepot snatches the bag of gems from you.>\n\nGazlowe calls this 10%? You tell him I'm going to weigh these!\n\nI suppose he expects me to pay you a delivery fee, as well? Fine, fine. Have some spoils!", sourceObjectiveStatus = "unverified-source-field" }
quests[26770] = { id = 26770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystic Masters", description = "The Needlerock mystics have taken control of the fungal giants that have sprouted in their chasm, down below. Now they seek to control our war constructs.\n\nGo north into Needlerock Slag and do something about it! Isn't that what you're here for?", sourceObjective = "Slay 5 Needlerock Mystics.", completion = "A few less stone troggs is always a good thing. Glad to see that you're a decent {class} after all.\n\nWe'll soon know the exact location where they're keeping my father captive. Hope you survive until then.", sourceObjectiveStatus = "unverified-source-field" }
quests[26771] = { id = 26771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Trap", description = "You must set the trap for the matriarch now.\n\nGo to the western end of the Alabaster Shelf and place the trapped basilisk meat in the center of the feeding grounds.", sourceObjective = "Place the trapped meat in the western end of the Alabaster Shelf.", progress = "It seems like the trap will work on Abyssion.", completion = "Well done, {name}.  Here's to hoping the trap performs as well when we try it on Abyssion.", sourceObjectiveStatus = "unverified-source-field" }
quests[26772] = { id = 26772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go northeast, and you will find the feathers, yes.", sourceObjective = "Obtain 5 Jungle Stalker Feathers from Jungle Stalkers in Northern Stranglethorn.", progress = "Raptor named Ohgan'aka, still your friend.", completion = "You bring feathers, yes.\n\nYou can follow directions, yes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26773] = { id = 26773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", sourceObjective = "Speak with Priestess Thaalia at Fort Livingston to participate in the Mind Vision ritual.", progress = "Your vision not Ohgan'aka's, no.\n\nYou are not ready.", completion = "What did Priestess tell you?\n\nThe raptor is daughter of Ohgan, heir to Mandokir's seat.\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26774] = { id = 26774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", sourceObjective = "Obtain Braddok's Big Brain from Braddok in Zul'Mamwe.", progress = "Extra-big spells need extra-big brains, yes.", completion = "Hold on, next part is tough, yes.\n\nLots of chances to fail, yes.\n\nBut {name} and {name}'aka going to be reunited... yes they will.", sourceObjectiveStatus = "unverified-source-field" }
quests[26775] = { id = 26775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", sourceObjective = "Speak with Priestess Thaalia, then help the Captured Lashtail Hatchling escape from Zul'Gurub.", progress = "Where is {name}'aka?", completion = "What a shame, yes.\n\nThis is what the spirits wanted, yes.\n\nMaybe when you are stronger, you will go into Zul'Gurub and take back your {name}'aka from Mandokir, yes.\n\nFor now, Priestess give you this.", sourceObjectiveStatus = "unverified-source-field" }
quests[26776] = { id = 26776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghaliri", description = "Priestess is not very good at speaking Common, no.\n\nMaybe you go speak with Ghaliri, in front of that tent.\n\nTell him about what you've seen inside Zul'Gurub, yes.", sourceObjective = "Report to Ghaliri at Fort Livingston in Northern Stranglethorn.", completion = "<You explain to Ghaliri what has happened up to this point.>\n\nIt would seem that Jin'do has survived, and he is rallying his brothers to once again summon Hakkar into this world.  It was good of you to come to speak with me.\n\nThere is not much we can do now but to wait, and watch.  Jin'do is weak, and prime for striking, but I must wait for word from Rastakhan before issuing orders.  Until then, you and your raptor will have to wait.", sourceObjectiveStatus = "unverified-source-field" }
quests[26777] = { id = 26777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing Spirits", description = "This is a tragic land, with a history of violence and despair. While many of the dead roam in the flesh, some are simply lost souls, wandering in confusion.\n\nThey deserve to be put at ease.\n\nMany of these souls gather at the Addle Stead to the south, appearing before travelers. Take this censer of holy incense. Sway it before the forlorn spirits, and let the offering of its gentle scent give them peace.", sourceObjective = "Use the Holy Censer to soothe 5 Forlorn Spirits at the Addle Stead.", completion = "You have brought peace to those who knew only misery, {name}. Be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26778] = { id = 26778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cries of the Dead", description = "Can you hear them, {name}? There's so many of them. They wander their graves, shuffling across the cold ground on rotting limbs.\n\nThe dead cry out in the still air. They suffer in their own flesh, forced from sleep! Every night I venture to the graveyard to put more of them to rest, but it's never enough.\n\nHelp me, {name}. Put the ghouls that swarm Raven Hill Cemetery out of their misery. Strike down as many as you can.", sourceObjective = "Kill 20 ghouls of any kind in Raven Hill Cemetery.", completion = "The cries grow softer for now. Light bless you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26779] = { id = 26779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel east into Zul'Mamwe and cull their wayward tribe.", sourceObjective = "Kill 16 Skullsplitter Trolls within Zul'Mamwe.", completion = "As promised, your reward.  You do the troll nation proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26780] = { id = 26780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nighttime in the Jungle", description = "Nighttime in Stranglethorn is a beautiful thing.  The skies fill with stars, and the moon casts its rays right between those leaves, right there.  I could stare at these skies all night.\n\nUnfortunately, the trolls that walk the ruins of Zul'Mamwe are interfering with my astronomy.  They burn braziers, day and night, which rob me of the darkness I need.\n\nPlease, {name}... travel east into Zul'Mamwe and put them out.", sourceObjective = "Put out 8 Zul'Mamwe Braziers at Zul'Mamwe in Northern Stranglethorn.", completion = "I can see the difference already.  I can't wait until later tonight, when I get to perform my observations again!", sourceObjectiveStatus = "unverified-source-field" }
quests[26781] = { id = 26781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind's Eye", description = "One of the Vale's many treasures lies nearby, on OUR side of the giant whirlpool.  The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the northeast.  His name is Mai'Zoth.  From what I understand, he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nThus far I've been unable to get near enough to take it from him.  Will you give it a try?", sourceObjective = "Obtain the Mind's Eye from Mai'Zoth.", progress = "Do you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, {name}!\n\nAnd to think my brother and sister said we wouldn't find anything of worth here in the Vale.  Hah!  And I'm just getting started!", sourceObjectiveStatus = "unverified-source-field" }
quests[26782] = { id = 26782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that some {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", sourceObjective = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26783] = { id = 26783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that a {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", sourceObjective = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26784] = { id = 26784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddied Waters", description = "The elemental powers are strong here in the Highlands, {name}. It is why the Twilight's Hammer chose to build their stronghold here.\n\nIn the right hands, we can channel this energy into something productive... like a portal directly to Orgrimmar.\n\nNorthwest of here, at the Verrall River Delta, water elementals have been stirred up by the actions of our foes upstream. Destroy them and gather 5 whirlpool cores. You'll not only calm the river, you'll power up our portal.", sourceObjective = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", progress = "I hope the fighting within the river wasn't too dangerous.", completion = "These are perfect! The restless waters of that troubled river will now do much more than move silt or stone... They'll move you across continents.\n\nFinish up the rest of your business here in Dragonmaw and then we should be able to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26785] = { id = 26785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Part of the Pack", description = "I've been trying to keep my true self hidden away from the people of Darkshire... they seem to react poorly to worgen. There are more of us here, though, beyond the city.\n\nThe companions I first traveled here with search the woods for wild worgen. They believe some of them, ones with telltale signs, can still be returned to sanity.\n\nI'm not quite ready to rejoin them. Please send word to Apprentice Fess at the crossroads west of town that I'll be staying in Darkshire a while longer.", sourceObjective = "Speak to Apprentice Fess at the crossroads west of Darkshire in Duskwood.", completion = "Tobias is staying in town still?\n\nMaster Harris warned him not to pursue his brother's fate. We all lead new lives now, after all. But the past is hard to let go of...", sourceObjectiveStatus = "unverified-source-field" }
quests[26786] = { id = 26786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Beach Head", description = "Something troubles me, {name}. The Twilight dragons knew just where and when to strike our airfleet. It's as if they knew our plans.\n\nTwilight spies cower within our midst!\n\nI'm going to take one of our remaining ships back to Orgrimmar to roll some heads. I need you to stay behind and secure this front. The Dragonmaw shaman are powerful; I have asked them to open up a portal to Orgrimmar, and I need you to help.\n\nSo. Start helping!", sourceObjective = "Speak with Artesh at Dragonmaw Port in Twilight Highlands.", completion = "Your Warchief is decisive, {name}. He makes things happen. I like him.\n\nLet's talk about this portal that he wants!", sourceObjectiveStatus = "unverified-source-field" }
quests[26787] = { id = 26787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bear In Mind", description = "I'm afraid that... well, I'm just plain afraid, but I'm also sorry to have to ask for another favor.\n\nMaster Harris needs brains. Bear brains. They're part of the serum apparently, or at least a proper substitute.\n\nThere's plenty of black bears in the woods to the west, and along the riverbank, but... I can't do it! I'm too terrified to go out there and face those huge things, even with a rifle. Please, let me pay you to bring back some!", sourceObjective = "Collect 8 Black Bear Brains.", progress = "Did you get them? Did you?", completion = "Thank you! Oh, thank you. I never thought I'd be happy to smell those brains, but I am now that I didn't have to get them!\n\nHere's your reward as promised...", sourceObjectiveStatus = "unverified-source-field" }
quests[26788] = { id = 26788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cementing Our Victory", description = "Our alliance with the Dragonmaw is secured, but this port is far from combat ready. These flimsy wooden walls are an embarrassment to the Warchief.\n\nWhen water elementals carve their way through rock, as they have in the Verrall River, they create a peculiar kind of muck. It spreads easily and dries harder than the hardest stone. It's the perfect mortar for large-scale construction.\n\nGo to the river delta northwest of here and collect some Verrall River muck. Even a little will go a long way.", sourceObjective = "Collect 10 piles of Verrall River Muck.", progress = "Do you have the mud? Construction of the new walls has already begun!", completion = "<Ornak allows the muck to drip from his fingertips.>\n\nNow that's the stuff! I'll start mixing and diluting this with gravel and water. Just a few handfuls of this can enhance enough cement for an entire stone tower.\n\nWe've got big plans for this port, {name}. You'll see!", sourceObjectiveStatus = "unverified-source-field" }
quests[26789] = { id = 26789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You no take axe!", description = "{name}, we have a problem! I've tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!", sourceObjective = "Kill 5 Test Kobolds.", sourceObjectiveStatus = "unverified-source-field" }
quests[26791] = { id = 26791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprout No More", description = "The stone trogg mystics are creating those fungal monstrosities from the giant mushrooms to the north.\n\nI want you to take a war guardian to help deal with the giants and stone troggs. Make your way to the giant mushrooms and target them. I and my geomancers will sink them into the ground before the mystics have a chance to finish their ritual.", sourceObjective = "Interact with and gain a War Guardian, and destroy 5 Giant Mushrooms.", progress = "Don't forget to use the war guardian to help you. The chasm is teeming with mystics and fungal monstrosities.", completion = "They won't have any more of those fungal giants to throw against us!", sourceObjectiveStatus = "unverified-source-field" }
quests[26792] = { id = 26792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Monstrosities", description = "Grab yourself a war guardian, and destroy those fungal monstrosities while you're out there.", sourceObjective = "Slay 5 Fungal Monstrosities.", completion = "Thank you, {name}. We've never had such a problem in Deepholm before the destruction of the World Pillar.\n\nYour Earthen Ring must repair the damage before it's too late.", sourceObjectiveStatus = "unverified-source-field" }
quests[26793] = { id = 26793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", sourceObjective = "Speak with Sirra Von'Indi in Darkshire.", completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections...", sourceObjectiveStatus = "unverified-source-field" }
quests[26794] = { id = 26794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", sourceObjective = "Speak with Commander Althea Ebonlocke in Darkshire.", completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A powerful undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26795] = { id = 26795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", sourceObjective = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", progress = "I don't blame you if you're having trouble with him, {name}. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, {name}! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however...", sourceObjectiveStatus = "unverified-source-field" }
quests[26796] = { id = 26796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", sourceObjective = "Speak with Watcher Sarah Ladimore in Darkshire.", completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he...", sourceObjectiveStatus = "unverified-source-field" }
quests[26797] = { id = 26797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, {name}.", sourceObjective = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n{name}. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love...", sourceObjectiveStatus = "unverified-source-field" }
quests[26798] = { id = 26798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Will be Pleased", description = "The portal is ready!\n\nIt's not powerful enough to transport an army, but we can maintain the connection long enough to allow important individuals to pass back and forth.\n\nThe Warchief will want to know about our progress here. Walk through the portal to Orgrimmar, then deliver the news to Garrosh Hellscream.", sourceObjective = "Use the portal in Dragonmaw Port to go to Orgrimmar and report to Garrosh Hellscream.", completion = "{class}, you've returned from Dragonmaw. The portal is functioning then? Good.\n\nBefore you return to your work there, we've got some dirty business to clean up right here in Orgrimmar...", sourceObjectiveStatus = "unverified-source-field" }
quests[26799] = { id = 26799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those That Couldn't Be Saved", description = "The val'kyr raise hundreds of corpses every day.  Agatha raised you just a few moments ago.  Not all are as lucky as you, however.\n\nSome maintain their free will, but live in constant fear and confusion.  They usually run off into the woods, cowering at their own reflections.\n\nOthers lose their minds completely, shambling about aimlessly.  They often turn to violence, and must be destroyed.\n\nThis is your task, {name}.  Destroy them, our former brothers and sisters though they might be.", sourceObjective = "Kill 6 Mindless Zombies.", completion = "Not even the power of the val'kyr was enough to save these creatures.  They were doomed from the beginning.\n\nI have obtained some equipment for you, {name}.  It's not much, but it will help.  Please, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[26800] = { id = 26800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruitment", description = "We've been shipping in dead bodies from Silverpine, Hillsbrad... hell, anywhere we can get them from.  We can't, however, afford to ignore the bodies which are sitting right on our front doorstep.\n\nThe last vestiges of the Scarlet Crusade roam here in Tirisfal Glades.  While we've managed to push them from Deathknell, several of their bodies litter the buildings to the north and the east.\n\nGo find them... and bring that Darnell fellow with you.  He looks strong enough to carry a few corpses.", sourceObjective = "Search Deathknell and the vicinity for 6 Scarlet Corpses, then point at them so Darnell can pick them up.", progress = "Have you managed to scavenge up some corpses?", completion = "Great work {name}.  I knew you weren't useless.\n\nHere, take one of these.  We deathguards have piles of these things just sitting around.", sourceObjectiveStatus = "unverified-source-field" }
quests[26801] = { id = 26801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge on our Perimeter", description = "If you're going to be an asset to the Forsaken, you need to learn how to fight.  And there's no better target than the Scourge minions that continue to pester us.\n\nThe wretched ghouls and Rattlecage skeletons that roam the north and to the east are former troopers of the fallen Scourge.  They should prove to be an even match for a fledgling {class} like you.\n\nDo not tarry - when you are done, speak to me again.", sourceObjective = "Kill 8 undead outside of Deathknell. You may kill either Wretched Ghouls or Rattlecage Skeletons.", progress = "Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let's hope you will fare better than them, yes?", completion = "You're growing in strength, {name}.  I've seen your type before.  You will be moving out of Deathknell and on to greater things before long.  Just make sure you don't lose sight of where you started.\n\nYou have much to accomplish, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26802] = { id = 26802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damned", description = "First of all, look at your armor.  You're a mess, {class}.\n\nIf you'd like to stay in one piece--and I've no doubt you do--perhaps I can help.  If you can gather some paws and wings from the wolves and bats nearby, maybe I'll find some armor for you.  You'll find the creatures to the north and to the west of here.", sourceObjective = "Obtain 4 Scavenger Paws and 4 Duskbat Wings.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, {name}. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26803] = { id = 26803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Reports", description = "Garrosh is brash and speaks harshly, but his intentions are good. In time, he will grow to see your people as a valuable ally.\n\nI am awaiting reports about recent Alliance activity in Durotar, but they haven't arrived yet. Would you be willing to visit Razor Hill and ask him for the reports in person? The easiest way to get there is by wind rider. Doras, Orgrimmar's wind rider master will let you use one of his wind riders for a small fee. Look for him on the rise north of the Valley of Strength.", sourceObjective = "Talk to Orgrimmar's wind rider master, Doras.", completion = "So you need to get to Razor Hill in a hurry? That's no problem at all. One of my wind riders will get you there very quickly and it only costs a few coins to hire one.", sourceObjectiveStatus = "unverified-source-field" }
quests[26804] = { id = 26804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Razor Hill", description = "When you're ready to take the wind rider down to Razor Hill, simply speak with me again. When you get there, waste no time in finding Gar'Thok. He's the one responsible for preparing reports on recent Alliance activity in Durotar.", sourceObjective = "Speak to Doras to purchase a wind rider ride to Razor Hill. Once you arrive, speak with Gar'Thok.", completion = "Eitrigg sent you? The warchief must be getting anxious to read my reports. I'd've sent them long ago, but each day we discover more about the Alliance's plans for invading Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26805] = { id = 26805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Cape!", description = "The Explorers' League is growing, {name}.  Not only have they taken in worgen like me, but they have expanded their range in search of artifacts.  One of our best, Bronwyn Hewstrike, has set up a camp in the south, where he believes an item of titan origin may be hidden.\n\nBronwyn asked me to perform some duties here in the north, one of which was to identify potential recruits.  You seem to be made of the right stuff.  Talk to Robert Rhodes, the flight master, and he'll send you down there.  Bronwyn's treat.", sourceObjective = "Speak with Robert Rhodes to obtain a flight to the Explorers' League Digsite in the Cape of Stranglethorn.", completion = "Wulfred has a good eye.  I think you'll do just fine here at my camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[26806] = { id = 26806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports to Orgrimmar", description = "Eitrigg will have to be happy with the part of the report that I've finished. Tell him to expect more in the future.\n\n<Gar'Thok hands you a stack of roughly folded papers.>\n\nThis should cover the most important details of the increase in Alliance forces working out of Northwatch. Please apologize to Eitrigg for me and let him know that we've had our hands full here, trying to keep Razor Hill secure and supplied. When you're ready to return to Orgrimmar, simply speak to Burok and hire a wind rider.", sourceObjective = "Take Gar'Thok's Reports to Burok at Razor Hill.", progress = "Are you ready to return to Orgrimmar?", completion = "Ready to return to Orgrimmar with those reports? I can arrange a flight for you right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[26807] = { id = 26807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Eitrigg", description = "Since you've already spoken to Doras, you'll be able to hire a wind rider to take you right back to Orgrimmar. Each time you arrive in a new town, be sure to speak with the town's flight master. After that, you'll be able to use the flight master's services to travel quickly.\n\nSpeak to me again when you're ready to purchase a return flight to Orgrimmar. Bring those reports to Eitrigg in the Valley of Strength once you've landed.", sourceObjective = "Speak with Burok and purchase a flight back to Orgrimmar. Once in Orgrimmar, bring Gar'Thok's Reports to Eitrigg in the Valley of Strength.", progress = "Did you bring those reports?", completion = "<Eitrigg examines the reports.>\n\nThe Alliance has grown bolder than we'd thought! I'll talk to the warchief about sending reinforcements right away. Thank you for getting these reports to me so quickly. I hope this coin is enough to cover your travel expenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[26808] = { id = 26808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maywiki", description = "<Linzi looks troubled.>\n\nYou know, there's a troll hiding behind that pile of boxes.  She must be awfully sad, if she doesn't want to come out and talk to anyone.\n\n<Linzi places some of the Akiris reeds in a kerchief and ties it together.>\n\nHere, give these to her.  They're very soft, and that maybe they will make her feel a little more comfortable back there.", sourceObjective = "Bring Linzi's Gift to Maywiki of Zuldazar at the Explorers' League Digsite.", progress = "Care to explain yourself, {class}?", completion = "<The troll looks into the package.>\n\nYou have my thanks.  You may tell your young dwarven friend that I am not sad.  I am waiting.  For you.\n\nI have identified you as the most promising {race} here in this strange town.  I have a task for you, if you would be willing to take it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26809] = { id = 26809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the north.  Hir'eek will guide you from there.", sourceObjective = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", progress = "You have not done as I asked, {race}.  Perhaps I was wrong to have selected you for this task...", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution.", sourceObjectiveStatus = "unverified-source-field" }
quests[26810] = { id = 26810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return switfly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", sourceObjective = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast.", sourceObjectiveStatus = "unverified-source-field" }
quests[26811] = { id = 26811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Maywiki entrusted this task to you.\n\nThe portal lies in wait in front of you.", sourceObjective = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26812] = { id = 26812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", sourceObjective = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26813] = { id = 26813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", sourceObjective = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26814] = { id = 26814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", sourceObjective = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", progress = "You've been on quite the adventure, I see.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[26815] = { id = 26815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI need his mixture for my next test.  Check the zombies to the north.", sourceObjective = "Obtain 5 vials of Zanzil's Mixture.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Dask carefully analyzes the strange compound.>\n\nThis mixture is... PERFECT!  Let's see what it does to your potentially-titan artifact here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26816] = { id = 26816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe for Disaster", description = "Did you see that explosion I made?  I must have flown 10 inches off the ground!\n\nI've just got to get Zanzil's recipe so I can find out why it did that.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the coast of the Cape, and snatch it for me!", sourceObjective = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nThanks again, {name}.  Remember, if you ever need anything mixed for you... and I mean ANYTHING... you can always ask The Flask.", sourceObjectiveStatus = "unverified-source-field" }
quests[26817] = { id = 26817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfectly Pure", description = "This humour won't serve on its own.  Too thick.  WAY too thick.\n\nThe nagas to our west maintain a shrine that dispenses the only clean water this side of Duskwood.  For most potions, I'll use river water, but Bronwyn demands accuracy!\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", sourceObjective = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Dask looks eagerly at your pack as you approach.>", completion = "Do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nAlright, let's get this mix started!", sourceObjectiveStatus = "unverified-source-field" }
quests[26818] = { id = 26818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plush Pelts", description = "Hi, I'm the town merchant!  And Bronwyn's my dad!\n\nSorry, I shouldn't get too excited.  Father says it's not professional.\n\nAnyhow, people always come to me asking for heavy leather, or rough hides, but I think they might also like it if I had some soft materials... like tiger fur!  Think you could get some for me?\n\nYou'll find a few panthers nearby, but if you want to see the big tigers, you'll have to go northwest from here... north of that big troll arena.", sourceObjective = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", progress = "Oooh... I hope they're soft!", completion = "<Linzi feels the hides and smiles to herself.>\n\nThese are so nice and cushy!  I think my customers are going to LOVE them!", sourceObjectiveStatus = "unverified-source-field" }
quests[26819] = { id = 26819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "The naga explorers to our west carry a valuable ocean reed - Akiris reeds.  Traders use them to make medicines and poultices, and craftsmen use them to line armor or even wrap cigars!\n\nIn the evenings, when digging's done, father's been teaching me how to use them... but unfortunately, we ran out.  Would you mind getting us some more?", sourceObjective = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Welcome back!", completion = "Hooray!  It's been days and days since we last had Akiris reeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[26820] = { id = 26820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They're Just Going to Leave Them Lying Around...", description = "Father says that a responsible merchant is always keeping an eye out for good deals.  I've been trying to look for deals everywhere I go, and I think I've just found one!\n\nThe naga to the west have dozens of statues that they place on the ground where they live.  They couldn't possibly need all of them... so I was thinking that we'd take some for ourselves!\n\nFree statues!  That's a good deal, right?", sourceObjective = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", progress = "Let's see 'em!", completion = "These statues are beautiful...\n\nWow, I had no idea the naga were so talented.  Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26821] = { id = 26821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airwyn Bantamflax", description = "Well, we have no idea what this artifact is.  It's old, older than dirt... but not titan.  I'm completely dumbstruck.\n\nAirwyn Bantamflax in Booty Bay is my direct superior.  Our next step should be to inform her of this find.  Please, would you bring it to her?", sourceObjective = "Bring the Opened Mosh'ogg Bounty to Airwyn Bantamflax at Booty Bay in the Cape of Stranglethorn.", progress = "Yes, {race}?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?", sourceObjectiveStatus = "unverified-source-field" }
quests[26822] = { id = 26822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good-Fer-Nothin' Slither-Dogs", description = "Ahem!  Hrm, hrm...\n\n<The dwarf clears his throat for several seconds.>\n\nYou're lookin' fer somethin' ta do?  And ya come askin' ME?  Lowly ol' Goris?!\n\nWell, ah... this is a first.  Ah, I've got it!\n\nThe vale ta tha north is filled with a bunch o' useless, belly-scrapin' basilisks.  They don't do nothin' for no one, and I hear they turned a guy ta stone once.\n\nIf ya kill 'em, I'll give ya some o' my stuff.", sourceObjective = "Kill 12 Thrashtail or Ironjaw Basilisks.", progress = "This is kinda fun.  Sendin' folks out ta do work for me... better than lousy ol' guard duty.", completion = "Ahem!  Ahhh... right...\n\nWell done!  And, congratulations, on killing them, I mean.\n\nHere you go.", sourceObjectiveStatus = "unverified-source-field" }
quests[26823] = { id = 26823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Big For His Britches", description = "Whatever it is you want to do: I've got a recipe that'll do exactly that.  You want an exploding potion?  BOOM!!  You want a lightning potion?  ZAP!!  You want a shrinking potion?  Smeerp.\n\nSo Bronwyn says he wants a carbon-dating potion?  Easy.  I could make that in my sleep.  The thing is... if we want it to be accurate, I need you to get some quality ingredients.\n\nStart with some humour from a basilisk to the north.  It'll need to be a pretty big basilisk...", sourceObjective = "Obtain a vial of Ironjaw Humour from the Ironjaw Behemoth in the Crystalvein Mine.", progress = "You got the task?  I got the flask.", completion = "Alright!  Step one - getting ingredients - is all done.  Time for the next step: getting more ingredients.", sourceObjectiveStatus = "unverified-source-field" }
quests[26824] = { id = 26824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Results: Inconclusive", description = "I did all I could, {name}.  I had the right potions... I had the right recipes... but the source of this sample eludes me.  It's tens of thousands of years old, but we've shown that it's not of titan origin.  And it's not saronite, I can tell you just by looking at it.  So... what in Brann's name is it?\n\nTell Bronwyn that I tried my best.  Sorry.", sourceObjective = "Return the Opened Mosh'Ogg Bounty to Bronwyn at the Explorers' League Camp in the Cape of Stranglethorn.", progress = "I saw smoke.  Everything alright?", completion = "I knew that alchemist was all talk.  Well, thanks for your help, {name}.  I know you tried.", sourceObjectiveStatus = "unverified-source-field" }
quests[26825] = { id = 26825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that <fella'/lass> that Wulfred was talkin' about!  The one who found the ogre artifact, and helped him test out those strange stones from up north.  Welcome to the digsite, {name}!\n\nWe were actually working on identifying those samples right as you got here.  Would you mind bringing the sample over to Dask?  I need him to help me find out how old it is.", sourceObjective = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[26826] = { id = 26826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that <fella'/lass> that Wulfred was talkin' about!  Welcome to the digsite, {name}.\n\nWe were actually just starting a project when you arrived.  Would you mind bringing this sample over to Dask?  I need him to help me find out how old it is.", sourceObjective = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[26827] = { id = 26827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Earthen Ring", description = "We must be rallyin' da Earthen Ring for dis fight. What we be lackin' in numbers, we make up for in strength.\n\nGo to tha temple and gather da restin' shaman from tha rear rooms. Norsala, Lorvarius, and I will be meetin' them at Lorthuna's Gate.", sourceObjective = "Rally 5 shaman in the rear of the Temple of Earth, and then speak to Maruut Stonebinder.", completion = "You've done what I thought not possible. Quite impressive, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26828] = { id = 26828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Part of the Bargain", description = "Sadly, I must stay and hold the rift, so you will have to battle without me. Go now to Therazane and join the battle, as promised. You should find her at the Halcyon Egress, north of Lorthuna's Gate and east of the Scoured Reach.\n\nWhen our part of the bargain is fulfilled, bring the last piece of the World Pillar here as quickly as possible.", sourceObjective = "Speak to Therazane on the Halcyon Egress.", completion = "And so you arrive, fleshling.  As promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[26829] = { id = 26829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone March", description = "My forces have already begun the assault. Join them. Spill the blood of these cultists upon the ground, that I might feel how they suffer.", sourceObjective = "Kill 15 Twilight Precipice Cultists.", completion = "Their blood upon the earth is a sweet thing. I shall cherish every moment, slowly extinguishing the stragglers from my realm.", sourceObjectiveStatus = "unverified-source-field" }
quests[26830] = { id = 26830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor's Bait", description = "I haven't given up my search for the Twilight's Hammer agents that lurk here in Orgrimmar. I need someone I can trust to collect the final evidence of treachery.\n\n<Hellscream pulls you aside.>\n\nSauranok the Mystic - my own most trusted advisor! - is under suspicion. Uncover the truth, {name}, and you'll be rewarded.\n\nI understand Twilight's Hammer has infiltrated workers at the airship docks, to spread their lies all over the continent. Question them. If you discover Sauranok's guilt... Kill him.", sourceObjective = "Question Orgrimmar Skyway Peons around the Zeppelin Towers. Look for any Suspicious Peons. Try to flush out Sauranok the Mystic and kill him.", progress = "Good to see you're still alive, {class}. How goes your investigation?", completion = "Sauranok, Sauranok. His own visions worked against him. Twilight's Hammer probably corrupted him from afar. Bah! Weak! We'll speak his name no more.\n\nI told him you were investigating the airship docks, {name}. To flush him out. Yes, I used you as bait. You served your Horde well, and deserve a reward for outing this viper from our midst.", sourceObjectiveStatus = "unverified-source-field" }
quests[26831] = { id = 26831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Flight", description = "Terrath wants you to make your way to the far end of the precipice to fight Zoltrik Drakebane. He is on his way there as well, but he thinks Zoltrik is likely to take to the sky.\n\nQuite an impression you seem to have made, little one. Have you ever mused that none of this would have happened if I had just stepped on you during our first meeting? Fate is a strange thing.", sourceObjective = "Defeat Zoltrik Drakebane.", progress = "It is good to see you on the battlefield again.", completion = "It is good that you were here. I find my size to be inhibiting when it comes to dragon riding, strangely.", sourceObjectiveStatus = "unverified-source-field" }
quests[26832] = { id = 26832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazane's Mercy", description = "There are two leaders among the Twilight that need to be killed.\n\nOne is a human by the name of Boldrich. Small, as you are. But still dangerous, as you also are.\n\nThe other is a priestess by the name of Lorthuna. She is wily and hard to corner. Strike swiftly and do not let her escape, or I promise you, you will regret it later.", sourceObjective = "Defeat Boldrich Stonerender and High Priestess Lorthuna.", completion = "You let Lorthuna escape? I warned you of this.\n\nStill, their forces are shattered and their resources cut off. There is little they can do to me or my allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26833] = { id = 26833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word In Stone", description = "You have done as I've asked of you, {race}. I shall honor my word. Gorsik will meet you at the temple with our piece of the World Pillar.\n\nFinish your ritual and bind the rift. After you have done such, tell your Earthen Ring to leave this place.\n\nYou however... you can stay for a time if you want. You've earned at least that.", sourceObjective = "Speak to Maruut Stonebinder in the Temple of Earth.", completion = "Gorsik has arrived. All of the pieces of the World Pillar are here, thanks to you.\n\nWhat you have done for us is immeasurable.  These final moments shall be the most crucial.  I hesitate to ask more of you, but I'd like you to stay with us and see this through.\n\nThe Twilight's Hammer was devastated by your attacks, but not destroyed.  It's no stretch to assume they will try to stop us from completing our ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[26834] = { id = 26834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Into the Chasm", description = "Down below in Needlerock Chasm is where the mystics are sprouting all of these fungal monstrosities. I sent Slate Quicksand and a small force to deal with it, but they've run into a snag.\n\nYou remember the Arch Geomancer? Would you fly down there to the northeast and lend him a hand?", sourceObjective = "Speak with Slate Quicksand at Needlerock Chasm in Deepholm.", completion = "Good to see you again, {name}. Now we'll get somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[26835] = { id = 26835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slight Problem", description = "While you were out there, Pyrium Lodestone contacted me. He said that there is a matter of great urgency and that your assistance is needed immediately. Return to him at the entrance to Needlerock Slag to the southwest.\n\nI wish you luck with the rescue of the Stonefather and the recovery of the middle fragment.", sourceObjective = "Return to Pyrium Lodestone at Needlerock Slag in Deepholm.", completion = "{name}, we have good news and a slight problem....", sourceObjectiveStatus = "unverified-source-field" }
quests[26836] = { id = 26836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Stonefather... and Flint", description = "We found out where the Stonefather is being held and young Flint ran off on his own to rescue him!\n\nI don't have to tell you that this is bad. Flint is going to get himself captured as well, or worse!\n\nThe stone trogg chieftain, Bouldergut, is at the end of the ledges above Needlerock Chasm to the north.\n\nPlease, {name}, you must go after Flint and free the Stonefather before we lose them both!", sourceObjective = "Free Stonefather Oremantle.", progress = "You must rescue Stonefather Oremantle. There's no time to waste, {name}!", completion = "{name}! You did it! How will we ever repay you?", sourceObjectiveStatus = "unverified-source-field" }
quests[26837] = { id = 26837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers' League Digsite", description = "Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn.  Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle.  I wonder what it is?", sourceObjective = "Report to Bronwyn Hewstrike at the Explorers' League Digsite in the Cape of Stranglethorn.Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn. Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle. I wonder what it is?", sourceObjectiveStatus = "unverified-source-field" }
quests[26838] = { id = 26838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebels Without a Clue", description = "Several years ago, Stormwind's Captain Kurzen brought a brigade into Stranglethorn Vale on a mission whose details are still murky.  Kurzen swiftly descended into madness, as did his men... except for a few rebels who made it their mission to undo the evils that Kurzen had wrought.\n\nAs I said, that was years ago.  I'm now hearing rumors that Kurzen is dead, but those rebels still persist at their rebellion.  If you wish to investigate, you'll find them at a camp on Stranglethorn's northern border.", sourceObjective = "Report to Lieutenant Doren at the Rebel Camp in Northern Stranglethorn.", completion = "Welcome to our camp, {class}.  You couldn't have arrived at a better time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26839] = { id = 26839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Away From It All!", description = "Say, {class}, you look tired.  Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn.  Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit.  I can tell just by looking that you need a break after so many difficult, lucrative adventures.", sourceObjective = "Visit Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.Say, {class}, you look tired. Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn. Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit. I can tell just by looking that you need a break after so many difficult, lucrative adventures.", sourceObjectiveStatus = "unverified-source-field" }
quests[26840] = { id = 26840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Highlands", description = "With Orgrimmar secure and our Dragonmaw allies behind us, we can turn our attention to the conquest of the Twilight Highlands and the utter destruction of Deathwing's forces there.\n\nI need the Horde's best on the front lines. That means you. And all your friends.\n\nThe Highlands WILL be ours!\n\nUse the new portal you created to return to Dragonmaw Port. Report to Zaela to see where she needs you the most.", sourceObjective = "Use the Twilight Highlands Portal in Orgrimmar to return to Dragonmaw Port in the Twilight Highlands and speak to Zaela.", completion = "{name}! I trust Orgrimmar fares well?\n\nAs you can see, construction of Dragonmaw Port continues at a breakneck pace. If my people questioned the Horde's power before... the sight of this imposing edifice and the speed in which it was constructed leaves no doubt.\n\nA new day dawns for the Dragonmaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[26841] = { id = 26841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Sigil", description = "This sigil was given to me by a messenger from our mage trainer, Rhyanda. It seems Rhyanda would have words with you when you have a moment. Read it and bring it to her afterwards.", sourceObjective = "Speak to Rhyanda inside Aldrassil in Shadowglen.", progress = "I'm glad that you've come, {name}.", completion = "I will be your mentor and guide for now. It is my duty to teach you the arcane arts and how you might best fit in among our people.\n\nAs you learn and grow in power, you will learn an immense variety of spells that should allow you to deal with nearly any situation. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26842] = { id = 26842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Gnoll-where", description = "Well met, {class}. We've got a problem, and I'd ask you to lend a hand.\n\nIt's gnolls. There's a mess of the things west of town, roaming the hills. Not usually any cause for alarm, but we've not usually had gnolls here in Loch Modan.\n\nI'm curious where they came from, but not curious enough to bother asking the mangy things. Clear 'em out, I say. Bring back proof of your kills and I'll pay a solid bounty.", sourceObjective = "Collect 12 Gnoll Ears from Mosshide Scouts or Mosshide Bashers.", progress = "Got some ears for me, then?", completion = "Nicely done, lad. I could use a {class} like you around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26843] = { id = 26843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny, Clever Commander", description = "We've dealt with kobolds in these lands for years. Not much other than a nuisance. But they've been getting craftier at their stealing.\n\nI think one of them's ended up smarter than usual. Won't be that way for long, though!\n\nI want you to go to the camp south of here and make sure there's not a \"big shot\" kobold stirrin' up the other ones. Make sure to check the cave; it's a likely spot.\n\nAnd don't be shy about clearing out the other kobolds along the way.", sourceObjective = "Slay Commander Nazrim.", progress = "Don't forget to find that \"commander\" down in the cave.", completion = "So I was right! Now the question is what the little freaks were plotting...", sourceObjectiveStatus = "unverified-source-field" }
quests[26844] = { id = 26844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold and Kobolder", description = "Now that those little blighters are dealt with, we've got more to take care of.\n\nThe tunnel rats are swarming all over the Silver Stream Mine, setting up camps and sniffing around further and further every day. Greedy little things are looking for loot, I gather.\n\nSurveying and foraging is all fine and dandy when it's not on dwarven land! Take care of those tunnel rats and report back to me.", sourceObjective = "Slay 5 Tunnel Rat Surveyors and 5 Tunnel Rat Foragers.", progress = "We'll deal with the mine proper once you've cleaned up the outer perimeter.", completion = "Good, good. Now we can see what's going on down in that mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[26845] = { id = 26845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who's In Charge Here?", description = "Dorli's filled me in on this crazy trogg-slave operation the kobolds have going, and if you haven't talked to her about it yet, I suggest you do.\n\nI'd like to get to the bottom of this. Literally! Whoever's running this show is bound to be at the bottom of the mine, calling the shots, and I want them dealt with.\n\nFind whatever crafty bugger is directing the geomancers and diggers and bring me back their head.", sourceObjective = "Collect the head of Foreman Sharpsneer.", progress = "I don't suppose it was Moira down there? Miracles do happen.", completion = "That's a gnoll head. Are you trying to pull some funny business, {name}?\n\nIf you're not, I've not the faintest idea what's going on here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26846] = { id = 26846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nasty Exploit", description = "I've found out what those rats are up to. There's so many of them outside because they've got troggs digging for them in the mine!\n\nThe tunnel rat geomancers figured out some kind of parlor trick to control the troggs, as creatures of the earth or somesuch.\n\nFascinating, but not something we want to let them practice. Take out those geomancers right away.", sourceObjective = "Slay 5 Tunnel Rat Geomancers.", completion = "I'm sure that only worked because the troggs aren't bright to begin with. But then again, us dwarves were once creatures of the earth as well.\n\nBeing bossed around by a kobold doesn't sound quite dignified, and I'm glad we didn't get to find out if they could pull that off.", sourceObjectiveStatus = "unverified-source-field" }
quests[26854] = { id = 26854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.\n\nIt's been days, and I've heard some beastly growls north of Helm's Bed Lake, west of the tunnel. Mori's tough as nails, but I'm worried.\n\nPlease, {name}. Find him.", sourceObjective = "Find Pilot Hildelve north of Helm's Bed Lake.", completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end.", sourceObjectiveStatus = "unverified-source-field" }
quests[26855] = { id = 26855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", sourceObjective = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot at the South Gate Outpost.", progress = "Hello, {name}.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, {name}. Your deed will be remembered by the pilots of the Ironforge Siege Brigade.", sourceObjectiveStatus = "unverified-source-field" }
quests[26856] = { id = 26856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel the Invasion", description = "This cavern was once a place of great honor. Young warriors were taken here to slay an Earthborer worm for their first kill - something we Orcs remember for our entire lives.\n\nThe Burning Blade agents inside have enslaved the cave's inhabitants and plan to launch a full-scale attack on Orgrimmar along with their Trogg allies.\n\nIf you strike down their Lieutenants, you may be able to catch them unprepared and stop this invasion before it starts.", sourceObjective = "Kill Oggleflint, Bazzalan, and Jergosh the Invoker.", completion = "You've done it, {name}! You've upturned the Searing Blade's invasion before it could even start! Take this, as a token of my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26857] = { id = 26857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssion's Minions", description = "If it's the dragon that's got the fragment, we're going to need to draw his attention back to his den.\n\nGo to Abyssion's Lair just east of here and defeat his underlings.  That should get him to show up with the World Pillar fragment sooner or later.", sourceObjective = "Defeat 8 Twilight or Dragonkin units at Abyssion's Lair.", completion = "That ought to get the dragon's attention, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26858] = { id = 26858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taragaman the Hungerer", description = "The Searing Blade has managed to summon a foul demon they call Taragaman the Hungerer to lead the first attack in their takeover of Orgrimmar!\n\nMake haste and slay Taragaman in the name of the Warchief! Lok'tar ogar!", sourceObjective = "Take Taragaman the Hungerer's heart.", progress = "If Taragaman is dead, show me his heart.", completion = "My children will sing songs of your glories, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26860] = { id = 26860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy {class}, you'll be any exception.\n\nYou get me some fresh bear rumps and leave the cooking to me!", sourceObjective = "Collect 8 Bear Rumps from Black Bears in Loch Modan.", progress = "I'm all ready to start cooking, do you have the bear meat for me?", completion = "Much obliged! The rump's part of my own secret twist on the recipe... but here's instructions on how to make it with any kind of bear meat.\n\nAnd here's a fresh batch of me own. Mind you eat them fresh!", sourceObjectiveStatus = "unverified-source-field" }
quests[26861] = { id = 26861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Block the Gates", description = "If we're to have a shot against Abyssion, we must make sure he receives no aid from reinforcements.\n\nYou will find two gateways in his lair to the east.  Use this stormstone to disrupt their operation.\n\nIf everything goes as planned, we'll be able to tackle Abyssion without him being able to receive much assistance.", sourceObjective = "Use the Stormstone at the Twilight Gate and Elemental Gate in Abyssion's Lair.", progress = "You've returned, {name}.  Are the gates closed?", completion = "Excellent.  When we make our move against Abyssion, we should be able to do so without reinforcements coming to his aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26862] = { id = 26862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Tampering", description = "The Searing Blade's warlocks have enslaved Ragefire Chasm's elemental spirits, {name}. They aren't a threat to the city while my spell keeps them at bay, but I can't maintain it much longer.\n\nBring me six of the Searing Bindings used to control them and I will release their spirits back into the Chasm.", sourceObjective = "Obtain 6 Searing Bindings.", progress = "Do you have the bindings?", completion = "Thank you, {class}. The Molten Elementals' spirits are finally back to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26863] = { id = 26863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now kobolds have moved in, putting their filthy paws on good, dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", sourceObjective = "Collect 6 loads of Miners' Gear from the Silver Stream Mine.", progress = "Do you have that Miners' Gear, {name}?", completion = "Did you see a lot of kobolds in there? The thought of their grimy hands clawing around our mine makes my stomach rumble!", sourceObjectiveStatus = "unverified-source-field" }
